import { type StylesConfig } from 'react-select';

const selectStyles: StylesConfig<any, false> = {
    control: (baseStyles, state) => ({
        ...baseStyles,
        minHeight: '36px',
        width: '100%',
        minWidth: 0,
        fontSize: '14px',
        borderRadius: '0.375rem',
        borderWidth: '1px',
        borderStyle: 'solid',
        borderColor: state.isFocused ? 'var(--ring)' : 'var(--input)',
        backgroundColor: 'var(--background)',
        color: 'var(--foreground)',
        outline: 'none',
        boxShadow: state.isFocused ? '0 0 0 3px color-mix(in oklab, var(--ring) 50%, transparent)' : 'none',
        transition: 'color 150ms, border-color 150ms, box-shadow 150ms',
        ':hover': {
            borderColor: state.isFocused ? 'var(--ring)' : 'var(--input)',
        },
    }),
    valueContainer: (base) => ({
        ...base,
        minWidth: 0,
        padding: '0 8px',
        backgroundColor: 'transparent',
    }),
    indicatorsContainer: (base) => ({
        ...base,
        backgroundColor: 'transparent',
    }),
    singleValue: (base) => ({
        ...base,
        color: 'var(--foreground)',
        fontSize: '14px',
    }),
    input: (base) => ({
        ...base,
        color: 'var(--foreground)',
        margin: 0,
        padding: 0,
        boxShadow: 'none',
        outline: 'none',
    }),
    placeholder: (base) => ({
        ...base,
        color: 'var(--muted-foreground)',
    }),
    menu: (base) => ({
        ...base,
        backgroundColor: 'var(--popover)',
        color: 'var(--popover-foreground)',
        border: '1px solid var(--border)',
        borderRadius: '0.375rem',
        boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)',
        overflow: 'hidden',
        zIndex: 50,
    }),
    menuPortal: (base) => ({
        ...base,
        zIndex: 60,
        // Radix Dialog (modal) desabilita pointer-events no <body> inteiro enquanto está aberto,
        // liberando só o próprio nó do modal. Como este menu é portalizado pro body, ele herda
        // esse bloqueio e fica inclicável sem essa reafirmação explícita.
        pointerEvents: 'auto',
    }),
    option: (base, state) => ({
        ...base,
        backgroundColor: state.isSelected
            ? 'var(--accent)'
            : state.isFocused
              ? 'color-mix(in oklab, var(--accent) 70%, var(--popover))'
              : 'var(--popover)',
        color: 'var(--foreground)',
        cursor: 'pointer',
        ':active': {
            backgroundColor: 'var(--accent)',
        },
    }),
    dropdownIndicator: (base) => ({
        ...base,
        color: 'var(--muted-foreground)',
        ':hover': {
            color: 'var(--foreground)',
        },
    }),
    clearIndicator: (base) => ({
        ...base,
        color: 'var(--muted-foreground)',
        ':hover': {
            color: 'var(--foreground)',
        },
    }),
    indicatorSeparator: (base) => ({
        ...base,
        backgroundColor: 'var(--border)',
    }),
    menuList: (base) => ({
        ...base,
        fontSize: '14px',
        backgroundColor: 'var(--popover)',
        padding: '4px',
    }),
    group: (base) => ({
        ...base,
        backgroundColor: 'var(--popover)',
        paddingTop: 0,
        paddingBottom: 0,
    }),
    groupHeading: (base) => ({
        ...base,
        backgroundColor: 'var(--popover)',
        color: 'var(--muted-foreground)',
    }),
    noOptionsMessage: (base) => ({
        ...base,
        backgroundColor: 'var(--popover)',
        color: 'var(--muted-foreground)',
    }),
    loadingMessage: (base) => ({
        ...base,
        backgroundColor: 'var(--popover)',
        color: 'var(--muted-foreground)',
    }),
};
export default selectStyles;

import * as React from 'react';
import { Bar, BarChart, CartesianGrid, Cell, XAxis, YAxis } from 'recharts';

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import moment from 'moment';

import { buildEquipmentBars, type ChartLine, type ChartPoint, parseEquipmentChart } from '@/lib/equipment-chart';
import { connectBackend } from '@/Utils/connectApi';
import { useEffect, useState } from 'react';
import { type ChartLoad, ChartLoadState } from './chart-load-state';

export function ChartAreaDashboard({ timerange, dateRange, customRange }: { timerange: string | number; dateRange?: any; customRange?: boolean }) {
    const [chartData, setChartData] = useState<ChartPoint[]>([]);
    const [lines, setLines] = useState<ChartLine[]>([]);
    const [load, setLoad] = useState<ChartLoad>({ status: 'loading' });
    const [attempt, setAttempt] = useState(0);

    function formatIsoDate(date: Date | string) {
        const d = date instanceof Date ? date : new Date(date);
        return moment(d).format('YYYY-MM-DD');
    }

    function formatBrDate(date: Date | string) {
        const d = date instanceof Date ? date : new Date(date);
        return moment(d).format('DD/MM/YYYY');
    }

    useEffect(() => {
        // Ignora a resposta de um período anterior que chegue depois da troca de período.
        let current = true;

        const getChartData = async () => {
            const query = new URLSearchParams();

            if (customRange && dateRange?.from && dateRange?.to) {
                query.set('from', formatIsoDate(dateRange.from));
                query.set('to', formatIsoDate(dateRange.to));
            }

            setLoad({ status: 'loading' });

            try {
                const response = await connectBackend.get(`chartEquipments/${timerange}${query.toString() ? `?${query.toString()}` : ''}`);
                if (!current) return;

                // Sem `lines`/`data` = sem dados (estado vazio); resposta que não é JSON = erro, nunca gráfico fictício.
                const parsed = parseEquipmentChart(response.data);
                if (!parsed.ok) {
                    setLoad({ status: 'error', message: parsed.reason });
                    return;
                }

                setChartData(parsed.data);
                setLines(parsed.lines);
                setLoad({ status: 'ready' });
            } catch {
                if (current) setLoad({ status: 'error', message: 'Não foi possível carregar o gráfico.' });
            }
        };

        getChartData();

        return () => {
            current = false;
        };
    }, [timerange, customRange, dateRange, attempt]);

    const barData = React.useMemo(() => buildEquipmentBars(lines, chartData), [chartData, lines]);

    const chartConfig = React.useMemo(() => {
        return {
            value: {
                label: 'Equipamentos',
                color: 'var(--chart-1)',
            },
        } satisfies ChartConfig;
    }, []);

    function formatAxisLabel(label: string) {
        return label.length > 10 ? `${label.slice(0, 9)}...` : label;
    }

    return (
        <Card className="@container/card">
            <CardHeader>
                <CardTitle>
                    {customRange && dateRange?.from && dateRange?.to
                        ? `Equipamentos recebidos • ${formatBrDate(dateRange.from)} até ${formatBrDate(dateRange.to)}`
                        : `Equipamentos recebidos • Últimos ${timerange} dias`}
                </CardTitle>

                <CardDescription>
                    <span className="hidden @[540px]/card:block">Total de equipamentos recebidos</span>
                </CardDescription>
            </CardHeader>

            <CardContent className="px-2 pt-4 sm:px-6 sm:pt-6">
                {load.status !== 'ready' ? (
                    <ChartLoadState load={load} onRetry={() => setAttempt((value) => value + 1)} />
                ) : barData.length === 0 ? (
                    <div className="flex h-[200px] w-full flex-col items-center justify-center rounded-md border border-dashed px-4 text-center">
                        <p className="text-sm font-medium">Sem equipamentos recebidos no período</p>
                        <p className="text-muted-foreground mt-1 text-xs">Altere o período ou registre uma ordem para gerar o gráfico.</p>
                    </div>
                ) : (
                    <ChartContainer config={chartConfig} className="aspect-auto h-[200px] w-full">
                        <BarChart data={barData} margin={{ top: 4, right: 8, left: 0, bottom: 0 }}>
                            <CartesianGrid vertical={false} />
                            <XAxis dataKey="label" tickLine={false} axisLine={false} tickMargin={8} minTickGap={12} tickFormatter={formatAxisLabel} />
                            <YAxis tickLine={false} axisLine={false} width={28} allowDecimals={false} />
                            <ChartTooltip
                                cursor={false}
                                content={
                                    <ChartTooltipContent
                                        hideLabel
                                        formatter={(value, _, item) => (
                                            <div className="flex w-full items-center justify-between gap-3">
                                                <span>{String(item.payload.label)}</span>
                                                <span className="font-mono font-medium tabular-nums">{Number(value || 0)}</span>
                                            </div>
                                        )}
                                    />
                                }
                            />
                            <Bar dataKey="value" name="value" radius={[4, 4, 0, 0]} maxBarSize={32}>
                                {barData.map((item) => (
                                    <Cell key={item.key} fill={item.fill} />
                                ))}
                            </Bar>
                        </BarChart>
                    </ChartContainer>
                )}
            </CardContent>
        </Card>
    );
}

import { connectBackend } from '@/Utils/connectApi';
import moment from 'moment';
import { useEffect, useState } from 'react';
import { Pie, PieChart } from 'recharts';
import { type ChartLoad, ChartLoadState } from './chart-load-state';

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';

import { ChartContainer, ChartLegend, ChartLegendContent, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';

type OrdersPoint = {
    period: string;
    entradas: number;
    concluidos: number;
    entregues: number;
};

export default function ChartFluxoOrders({
    timerange,
    dateRange,
    customRange,
}: {
    timerange: string | number;
    dateRange?: any;
    customRange?: boolean;
}) {
    const [orders, setOrders] = useState<OrdersPoint[]>([]);
    const [load, setLoad] = useState<ChartLoad>({ status: 'loading' });
    const [attempt, setAttempt] = useState(0);

    function formatIsoDate(date: Date | string) {
        const d = date instanceof Date ? date : new Date(date);
        return moment(d).format('YYYY-MM-DD');
    }

    function formatBrDate(date: Date | string) {
        const d = date instanceof Date ? date : new Date(date);
        return moment(d).format('DD/MM/YYYY');
    }

    useEffect(() => {
        let current = true;

        const getOrders = async () => {
            setLoad({ status: 'loading' });
            try {
                const query = new URLSearchParams();

                if (customRange && dateRange?.from && dateRange?.to) {
                    query.set('from', formatIsoDate(dateRange.from));
                    query.set('to', formatIsoDate(dateRange.to));
                }

                const response = await connectBackend.get(`fluxsOrders/${timerange}${query.toString() ? `?${query.toString()}` : ''}`);
                if (!current) return;
                // A API devolve uma lista por dia; outro formato (ex.: página de login) é erro, não "sem dados".
                if (!Array.isArray(response.data)) {
                    setLoad({ status: 'error', message: 'Resposta inesperada do servidor.' });
                    return;
                }
                setOrders(response.data);
                setLoad({ status: 'ready' });
            } catch (error) {
                console.error('Erro ao carregar dados do gráfico Fluxo de ordens', error);
                if (current) setLoad({ status: 'error', message: 'Não foi possível carregar o gráfico.' });
            }
        };
        getOrders();

        return () => {
            current = false;
        };
    }, [timerange, customRange, dateRange, attempt]);

    const chartConfig = {
        entradas: {
            label: 'Entradas',
            color: 'var(--chart-1)',
        },
        concluidos: {
            label: 'Concluídos',
            color: 'var(--chart-2)',
        },
        entregues: {
            label: 'Entregues',
            color: 'var(--chart-3)',
        },
    };

    const pieData = [
        {
            key: 'entradas',
            label: 'Entradas',
            value: orders.reduce((acc, item) => acc + Number(item.entradas || 0), 0),
            fill: 'var(--chart-1)',
        },
        {
            key: 'concluidos',
            label: 'Concluídos',
            value: orders.reduce((acc, item) => acc + Number(item.concluidos || 0), 0),
            fill: 'var(--chart-2)',
        },
        {
            key: 'entregues',
            label: 'Entregues',
            value: orders.reduce((acc, item) => acc + Number(item.entregues || 0), 0),
            fill: 'var(--chart-3)',
        },
    ].filter((item) => item.value > 0);

    return (
        <Card className="@container/card">
            <CardHeader>
                <CardTitle>
                    {customRange && dateRange?.from && dateRange?.to
                        ? `Fluxo de Ordens • ${formatBrDate(dateRange.from)} até ${formatBrDate(dateRange.to)}`
                        : `Fluxo de Ordens Últimos • ${timerange} dias`}
                </CardTitle>

                <CardDescription>
                    <span className="hidden @[540px]/card:block">Entradas x Concluídos x Entregues</span>
                </CardDescription>
            </CardHeader>

            <CardContent className="px-2 pt-4 sm:px-6 sm:pt-6">
                {load.status !== 'ready' ? (
                    <ChartLoadState load={load} onRetry={() => setAttempt((value) => value + 1)} />
                ) : pieData.length === 0 ? (
                    <div className="flex h-[200px] w-full flex-col items-center justify-center rounded-md border border-dashed px-4 text-center">
                        <p className="text-sm font-medium">Sem movimentação de ordens no período</p>
                        <p className="text-muted-foreground mt-1 text-xs">Altere o período ou registre uma ordem para acompanhar o fluxo.</p>
                    </div>
                ) : (
                    <ChartContainer config={chartConfig} className="aspect-auto h-[200px] w-full">
                        <PieChart>
                            <ChartTooltip cursor={false} content={<ChartTooltipContent nameKey="key" hideLabel />} />
                            <Pie data={pieData} dataKey="value" nameKey="label" innerRadius={45} outerRadius={80} strokeWidth={2} />
                            <ChartLegend
                                align="left"
                                verticalAlign="middle"
                                layout="vertical"
                                content={<ChartLegendContent nameKey="key" className="flex-col items-start justify-start pt-0 pl-2" />}
                            />
                        </PieChart>
                    </ChartContainer>
                )}
            </CardContent>
        </Card>
    );
}

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { CartesianGrid, Line, LineChart, XAxis, YAxis } from 'recharts';

const chartConfig = {
    rate: {
        label: 'Taxa (%)',
        color: '#0f766e',
    },
} satisfies ChartConfig;

export function ChartFollowUpTrend({
    title,
    description,
    trend,
}: {
    title: string;
    description: string;
    trend?: { granularity?: string; data?: Array<{ label: string; rate: number; contacted: number; recovered: number }> };
}) {
    const data = trend?.data ?? [];

    return (
        <Card>
            <CardHeader>
                <CardTitle>{title}</CardTitle>
                <CardDescription>{description}</CardDescription>
            </CardHeader>
            <CardContent className="px-2 pt-4 sm:px-6 sm:pt-6">
                <ChartContainer config={chartConfig} className="aspect-auto h-[280px] w-full">
                    <LineChart data={data} margin={{ top: 8, right: 12, left: 12, bottom: 0 }}>
                        <CartesianGrid vertical={false} />
                        <XAxis dataKey="label" tickLine={false} axisLine={false} minTickGap={18} />
                        <YAxis tickLine={false} axisLine={false} width={44} domain={[0, 'auto']} />
                        <ChartTooltip
                            content={
                                <ChartTooltipContent
                                    formatter={(value, _name, item: any) => (
                                        <>
                                            <span>Taxa</span>
                                            <span>{Number(value).toFixed(1)}%</span>
                                            <span className="text-muted-foreground block w-full text-[11px]">
                                                {item?.payload?.recovered ?? 0} recuperado(s) / {item?.payload?.contacted ?? 0} contato(s)
                                            </span>
                                        </>
                                    )}
                                />
                            }
                        />
                        <Line type="monotone" dataKey="rate" stroke="var(--color-rate)" strokeWidth={2.5} dot={{ r: 3 }} activeDot={{ r: 5 }} />
                    </LineChart>
                </ChartContainer>
            </CardContent>
        </Card>
    );
}

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from '@/components/ui/chart';
import { CartesianGrid, Line, LineChart, ReferenceLine, XAxis, YAxis } from 'recharts';

const chartConfig = {
    rate: {
        label: 'Taxa de retorno (%)',
        color: '#0f766e',
    },
    threshold: {
        label: 'Limite (%)',
        color: '#dc2626',
    },
} satisfies ChartConfig;

export function ChartQualityTrend({
    trend,
    threshold,
}: {
    trend?: { granularity?: string; data?: Array<{ label: string; rate: number; returns: number; total_orders: number }> };
    threshold?: number;
}) {
    const data = trend?.data ?? [];
    const granularityLabel = trend?.granularity === 'monthly' ? 'mensal' : trend?.granularity === 'weekly' ? 'semanal' : 'diaria';

    return (
        <Card>
            <CardHeader>
                <CardTitle>Tendência de retorno em garantia</CardTitle>
                <CardDescription>Evolução {granularityLabel} da taxa de retorno em garantia no período selecionado.</CardDescription>
            </CardHeader>
            <CardContent className="px-2 pt-4 sm:px-6 sm:pt-6">
                <ChartContainer config={chartConfig} className="aspect-auto h-[280px] w-full">
                    <LineChart data={data} margin={{ top: 8, right: 12, left: 12, bottom: 0 }}>
                        <CartesianGrid vertical={false} />
                        <XAxis dataKey="label" tickLine={false} axisLine={false} minTickGap={18} />
                        <YAxis tickLine={false} axisLine={false} width={44} domain={[0, 'auto']} />
                        <ChartTooltip
                            content={
                                <ChartTooltipContent
                                    formatter={(value, name, item: any) => {
                                        if (name === 'rate') {
                                            return (
                                                <>
                                                    <span>Taxa</span>
                                                    <span>{Number(value).toFixed(1)}%</span>
                                                    <span className="text-muted-foreground block w-full text-[11px]">
                                                        {item?.payload?.returns ?? 0} retornos / {item?.payload?.total_orders ?? 0} ordens
                                                    </span>
                                                </>
                                            );
                                        }

                                        return (
                                            <>
                                                <span>Limite</span>
                                                <span>{Number(value).toFixed(1)}%</span>
                                            </>
                                        );
                                    }}
                                />
                            }
                        />
                        <ReferenceLine y={threshold ?? 0} stroke="var(--color-threshold)" strokeDasharray="4 4" />
                        <Line type="monotone" dataKey="rate" stroke="var(--color-rate)" strokeWidth={2.5} dot={{ r: 3 }} activeDot={{ r: 5 }} />
                    </LineChart>
                </ChartContainer>
            </CardContent>
        </Card>
    );
}

import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@/components/ui/dialog';

import InputError from '@/components/input-error';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Separator } from '@/components/ui/separator';

import { formatBRL } from '@/lib/money';
import { maskCpfCnpj } from '@/Utils/mask';
import { router, useForm, usePage } from '@inertiajs/react';
import { useState } from 'react';

interface SaleInvoiceModalProps {
    open: boolean;
    onClose: () => void;
    sale: {
        customer?: Array<{
            name?: string;
            cpfcnpj?: string;
        }>;
        items?: Array<{
            name?: string;
            selected_quantity?: number;
            sale_price?: string | number;
        }>;
        total?: string | number;
        fiscal_document_number?: string;
        fiscal_document_url?: string;
        fiscal_issued_at?: string;
        fiscal_notes?: string;
        numberSale: {
            id?: string | number;
        };
    };
}

export default function SaleInvoiceModal({ open, onClose, sale }: SaleInvoiceModalProps) {
    const { fiscalSetting } = usePage().props as any;
    const saleId = sale?.numberSale?.id;
    const totalSale = Number(sale?.total ?? 0);
    const canIssueInvoice = totalSale > 0;
    const hasRegisteredFiscal = Boolean(sale?.fiscal_document_number || sale?.fiscal_document_url);
    const nativeNfe = Boolean(fiscalSetting?.native?.nfe);
    const nativeNfce = Boolean(fiscalSetting?.native?.nfce);
    const hasNative = nativeNfe || nativeNfce;
    const [emitting, setEmitting] = useState<string | null>(null);

    const handleEmit = (model: 'nfe' | 'nfce') => {
        if (!saleId) return;

        setEmitting(model);
        router.post(
            route('app.sales.fiscal.emit', saleId),
            { model },
            {
                preserveScroll: true,
                onSuccess: () => onClose(),
                onFinish: () => setEmitting(null),
            },
        );
    };
    const { data, setData, post, processing, errors } = useForm({
        fiscal_document_number: '',
        fiscal_document_url: '',
        fiscal_issued_at: '',
        fiscal_notes: '',
    });

    const handleRegisterFiscal = () => {
        if (!saleId) return;

        post(route('app.sales.fiscal.register', saleId), {
            preserveScroll: true,
            onSuccess: () => onClose(),
        });
    };

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="scrollbar-default max-h-[calc(100svh-1rem)] w-[calc(100%-1rem)] max-w-md overflow-y-auto overscroll-contain p-4 sm:max-h-[90svh] sm:w-full sm:p-6">
                <DialogHeader>
                    <DialogTitle>{hasNative ? 'Emitir nota fiscal da venda' : 'Emitir NF-e de produtos'}</DialogTitle>

                    <DialogDescription>
                        {hasNative
                            ? 'A nota é emitida pelo sistema e acompanhada em Notas fiscais.'
                            : 'Use os dados da venda para emitir a NF-e no portal fiscal do emissor e registre o comprovante abaixo.'}
                    </DialogDescription>
                </DialogHeader>

                <Card>
                    <CardContent className="space-y-2 pt-4 text-sm">
                        <div>
                            <span className="font-medium">Cliente:</span> {sale.customer?.[0]?.name ?? 'Venda avulsa'}
                        </div>

                        <div>
                            <span className="font-medium">CPF/CNPJ:</span> {maskCpfCnpj(sale.customer?.[0]?.cpfcnpj ?? '')}
                        </div>

                        <Separator />

                        <div className="font-medium">Produtos</div>

                        <div>
                            <span className="font-medium">Série padrão:</span> {fiscalSetting?.default_nfe_series || 'Não configurada'}
                        </div>

                        {sale.items?.map((item, index: number) => (
                            <div key={index} className="flex justify-between text-sm">
                                <span>
                                    {item?.name} x {item.selected_quantity}
                                </span>

                                <span>{formatBRL(item.sale_price ?? '')}</span>
                            </div>
                        ))}

                        <Separator />

                        <div className="flex justify-between font-medium">
                            <span>Total</span>

                            <span>{formatBRL(sale.total ?? '')}</span>
                        </div>

                        {!canIssueInvoice ? (
                            <div className="rounded-md border border-amber-200 bg-amber-50 p-2 text-amber-900">
                                Informe um valor maior que zero na venda para emitir a NF-e.
                            </div>
                        ) : null}

                        <div>
                            <span className="font-medium">Venda N°:</span> {sale?.numberSale?.id ?? '-'}
                        </div>
                    </CardContent>
                </Card>

                {hasNative && !hasRegisteredFiscal ? (
                    <div className="flex flex-wrap justify-end gap-2">
                        {nativeNfce && (
                            <Button
                                type="button"
                                variant={nativeNfe ? 'outline' : 'default'}
                                disabled={!canIssueInvoice || emitting !== null}
                                onClick={() => handleEmit('nfce')}
                            >
                                {emitting === 'nfce' ? 'Enviando...' : 'Emitir NFC-e'}
                            </Button>
                        )}
                        {nativeNfe && (
                            <Button
                                type="button"
                                disabled={!canIssueInvoice || emitting !== null || !sale.customer?.length}
                                onClick={() => handleEmit('nfe')}
                            >
                                {emitting === 'nfe' ? 'Enviando...' : 'Emitir NF-e'}
                            </Button>
                        )}
