import { toastWarning } from '@/components/app-toast-messages';
import { Icon } from '@/components/icon';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import AppLayout from '@/layouts/app-layout';
import { cn } from '@/lib/utils';
import { BreadcrumbItem } from '@/types';
import { maskCep, maskCnpj, maskPhone, unMask } from '@/Utils/mask';
import { Head, useForm, usePage } from '@inertiajs/react';
import { Building, Save, UploadCloud } from 'lucide-react';
import { DragEvent, useEffect, useRef, useState } from 'react';

const breadcrumbs: BreadcrumbItem[] = [
    {
        title: 'Painel',
        href: route('app.dashboard'),
    },
    {
        title: 'Dados da empresa',
        href: '#',
    },
];

export default function Company({ company }: any) {
    const { auth } = usePage<{ auth?: { permissions?: string[] } }>().props;
    const canManageCompany = auth?.permissions?.includes('company');
    const [isDraggingLogo, setIsDraggingLogo] = useState(false);
    const [logoPreview, setLogoPreview] = useState<string | null>(null);
    const logoInputRef = useRef<HTMLInputElement>(null);
    const { data, setData, processing, errors, post, transform } = useForm({
        shortname: company?.shortname,
        companyname: company?.companyname,
        cnpj: company?.cnpj,
        logo: null as File | null,
        zip_code: company?.zip_code,
        state: company?.state,
        city: company?.city,
        district: company?.district,
        street: company?.street,
        number: company?.number,
        complement: company?.complement,
        telephone: company?.telephone,
        whatsapp: company?.whatsapp,
        site: company?.site,
        email: company?.email,
    });
    const currentLogoSrc = company?.logo ? `/storage/logos/${company.logo}` : '/images/default.png';

    const handleLogoFile = (file?: File) => {
        if (!file) return;

        if (!['image/png', 'image/jpeg', 'image/gif', 'image/webp'].includes(file.type)) {
            toastWarning('Erro', 'Apenas imagens são permitidas para o logotipo.');
            return;
        }

        if (file.size > 2 * 1024 * 1024) {
            toastWarning('Erro', 'O logotipo deve ter no máximo 2 MB.');
            return;
        }

        if (logoPreview) {
            URL.revokeObjectURL(logoPreview);
        }

        setData('logo', file);
        setLogoPreview(URL.createObjectURL(file));
    };

    const handleLogoDrop = (e: DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDraggingLogo(false);

        if (!canManageCompany) return;

        handleLogoFile(e.dataTransfer.files?.[0]);
    };

    useEffect(() => {
        return () => {
            if (logoPreview) {
                URL.revokeObjectURL(logoPreview);
            }
        };
    }, [logoPreview]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (processing || !canManageCompany) return;

        transform((values) => ({ ...values, _method: 'put' }));
        post(route('app.company.update', company.id), {
            preserveScroll: true,
            forceFormData: true,
            onSuccess: () => {
                setData('logo', null);
                setLogoPreview(null);
                if (logoInputRef.current) logoInputRef.current.value = '';
            },
            onError: (validationErrors) => {
                toastWarning('Revise os dados informados', Object.values(validationErrors).join(' '));
            },
        });
    };

    const getCep = (zip_code: string) => {
        const cleanCep = unMask(zip_code);
        fetch(`https://viacep.com.br/ws/${cleanCep}/json/`)
            .then((response) => response.json())
            .then((result) => {
                setData((data) => ({ ...data, state: result.uf }));
                setData((data) => ({ ...data, city: result.localidade }));
                setData((data) => ({ ...data, district: result.bairro }));
                setData((data) => ({ ...data, street: result.logradouro }));
                setData((data) => ({ ...data, complement: result.complemento }));
            })
            .catch((error) => console.error(error));
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="Dados da empresa" />
            <div className="flex min-h-16 flex-col justify-center gap-1 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={Building} className="h-8 w-8" />
                    <h2 className="text-xl font-semibold tracking-tight">Dados da empresa</h2>
                </div>
            </div>

            <div className="flex items-center justify-between p-4">
                <div></div>
            </div>

            <div className="p-4">
                <div className="rounded-lg border p-2">
                    <form onSubmit={handleSubmit} autoComplete="off" className="space-y-8">
                        <div className="grid gap-2">
                            <Label htmlFor="logo">Logotipo</Label>
                            <div
                                onDragEnter={(e) => {
                                    e.preventDefault();
                                    if (canManageCompany) setIsDraggingLogo(true);
                                }}
                                onDragOver={(e) => {
                                    e.preventDefault();
                                    if (canManageCompany) setIsDraggingLogo(true);
                                }}
                                onDragLeave={(e) => {
                                    e.preventDefault();
                                    if (e.currentTarget.contains(e.relatedTarget as Node)) return;
                                    setIsDraggingLogo(false);
                                }}
                                onDrop={handleLogoDrop}
                                onClick={() => canManageCompany && logoInputRef.current?.click()}
                                onKeyDown={(e) => {
                                    if (!canManageCompany) return;
                                    if (e.key === 'Enter' || e.key === ' ') {
                                        e.preventDefault();
                                        logoInputRef.current?.click();
                                    }
                                }}
                                role="button"
                                tabIndex={canManageCompany ? 0 : -1}
                                aria-disabled={!canManageCompany}
                                className={cn(
                                    'border-muted-foreground/30 bg-muted/20 flex min-h-36 items-center gap-4 rounded-lg border-2 border-dashed p-4 transition-colors',
                                    canManageCompany ? 'cursor-pointer' : 'cursor-not-allowed opacity-70',
                                    isDraggingLogo && 'border-primary bg-primary/5',
                                )}
                            >
                                <div className="bg-background flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-md border p-2">
                                    <img
                                        src={logoPreview ?? currentLogoSrc}
                                        alt="Imagem de logo"
                                        className="max-h-full max-w-full object-contain"
                                        onError={(event) => {
                                            event.currentTarget.src = '/images/default.png';
                                        }}
                                    />
                                </div>
                                <div className="min-w-0">
                                    <UploadCloud className="text-muted-foreground mb-2 h-6 w-6" />
                                    <p className="text-sm font-medium">Arraste o logotipo aqui ou clique para selecionar</p>
                                    <p className="text-muted-foreground mt-1 text-xs">PNG, JPG, GIF ou WEBP até 2 MB.</p>
                                    {data.logo && <p className="text-muted-foreground mt-2 truncate text-xs">{(data.logo as File).name}</p>}
                                </div>
                                <Input
                                    ref={logoInputRef}
                                    type="file"
                                    id="logo"
                                    accept="image/png,image/jpeg,image/gif,image/webp"
                                    disabled={!canManageCompany}
                                    onChange={(e) => handleLogoFile(e.target.files?.[0])}
                                    className="sr-only"
                                />
                            </div>
                            {errors.logo && <div className="text-sm text-red-500">{errors.logo}</div>}
                        </div>

                        <div className="mt-4 grid gap-4 md:grid-cols-3">
                            <div className="grid gap-2">
                                <Label htmlFor="name">CPF/CNPJ</Label>
                                <Input
                                    type="text"
                                    id="cnpj"
                                    value={maskCnpj(data.cnpj)}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('cnpj', e.target.value)}
                                    maxLength={18}
                                />
                                {errors.cnpj && <div className="text-sm text-red-500">{errors.cnpj}</div>}
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="shortname">Nome curto (para etiqueta)</Label>
                                <Input
                                    type="text"
                                    id="shortname"
                                    value={data.shortname}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('shortname', e.target.value)}
                                />
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="companyname">Razão social</Label>
                                <Input
                                    type="text"
                                    id="companyname"
                                    value={data.companyname}
                                    maxLength={150}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('companyname', e.target.value)}
                                />
                                <p className="text-muted-foreground text-xs">
                                    Igual ao cadastro na Receita (até 150 caracteres). Na emissão automática de notas, o emissor aceita até 80.
                                </p>
                                {errors.companyname && <div className="text-sm text-red-500">{errors.companyname}</div>}
                            </div>
                        </div>

                        <div className="mt-4 grid gap-4 md:grid-cols-6">
                            <div className="grid gap-2">
                                <Label htmlFor="zip_code">CEP</Label>
                                <Input
                                    type="text"
                                    id="zip_code"
                                    value={maskCep(data.zip_code)}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('zip_code', e.target.value)}
                                    onBlur={(e) => getCep(e.target.value)}
                                    maxLength={9}
                                />
                                {errors.zip_code && <div className="text-sm text-red-500">{errors.zip_code}</div>}
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="state">UF</Label>
                                <Input
                                    type="text"
                                    id="state"
                                    value={data.state}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('state', e.target.value)}
                                />
                                {errors.state && <div>{errors.state}</div>}
                            </div>

                            <div className="grid gap-2 md:col-span-2">
                                <Label htmlFor="city">Cidade</Label>
                                <Input
                                    type="text"
                                    id="city"
                                    value={data.city}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('city', e.target.value)}
                                />
                                {errors.city && <div className="text-sm text-red-500">{errors.city}</div>}
                            </div>

                            <div className="grid gap-2 md:col-span-2">
                                <Label htmlFor="district">Bairro</Label>
                                <Input
                                    type="text"
                                    id="district"
                                    value={data.district}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('district', e.target.value)}
                                />
                                {errors.district && <div className="text-sm text-red-500">{errors.district}</div>}
                            </div>
                        </div>

                        <div className="mt-4 grid gap-4 md:grid-cols-4">
                            <div className="grid gap-2 md:col-span-2">
                                <Label htmlFor="street">Logradouro</Label>
                                <Input
                                    type="text"
                                    id="street"
                                    value={data.street}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('street', e.target.value)}
                                />
                                {errors.street && <div className="text-sm text-red-500">{errors.street}</div>}
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="number">Número</Label>
                                <Input
                                    type="text"
                                    id="number"
                                    value={data.number}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('number', e.target.value)}
                                />
                                {errors.number && <div className="text-sm text-red-500">{errors.number}</div>}
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="complement">Complemento</Label>
                                <Input
                                    type="text"
                                    id="complement"
                                    value={data.complement}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('complement', e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="mt-4 grid gap-4 md:grid-cols-6">
                            <div className="grid gap-2">
                                <Label htmlFor="telephone">Telefone</Label>
                                <Input
                                    type="text"
                                    id="telephone"
                                    value={maskPhone(data.telephone)}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('telephone', e.target.value)}
                                    maxLength={15}
                                />
                                {errors.telephone && <div className="text-sm text-red-500">{errors.telephone}</div>}
                            </div>

                            <div className="grid gap-2">
                                <Label htmlFor="whatsapp">Whatsapp</Label>
                                <Input
                                    type="text"
                                    id="whatsapp"
                                    value={maskPhone(data.whatsapp)}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('whatsapp', e.target.value)}
                                    maxLength={15}
                                />
                            </div>

                            <div className="grid gap-2 md:col-span-2">
                                <Label htmlFor="site">Site</Label>
                                <Input
                                    type="text"
                                    id="site"
                                    value={data.site}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('site', e.target.value)}
                                />
                            </div>

                            <div className="grid gap-2 md:col-span-2">
                                <Label htmlFor="email">E-mail</Label>
                                <Input
                                    type="text"
                                    id="email"
                                    value={data.email}
                                    disabled={!canManageCompany}
                                    onChange={(e) => setData('email', e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="flex justify-end">
                            {canManageCompany && (
                                <Button type="submit" disabled={processing}>
                                    <Save />
                                    Salvar
                                </Button>
                            )}
                        </div>
                    </form>
                </div>
            </div>
        </AppLayout>
    );
}

import { toastSuccess } from '@/components/app-toast-messages';
import { DatePicker } from '@/components/date-picker';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { useZipcodeAutocomplete } from '@/hooks/useZipcodeAutocomplete';
import { Customer } from '@/types';
import { maskCep, maskCpfCnpj, maskPhone, unMask } from '@/Utils/mask';
import { useForm } from '@inertiajs/react';
import { AlertTriangle, Loader2Icon, Save, Search } from 'lucide-react';
import { useEffect, useState } from 'react';

type DuplicateCustomer = {
    id: number;
    customer_number: number;
    name: string;
};

export default function CustomerForm({ initialData }: { initialData?: Customer }) {
    const isEdit = !!initialData;

    const [zipcodeToSearch, setZipcodeToSearch] = useState<string | null>(null);
    const [duplicateCustomers, setDuplicateCustomers] = useState<DuplicateCustomer[]>([]);

    const { data, setData, post, processing, reset, setError, clearErrors, errors, put } = useForm<Customer>(initialData || ({} as Customer));

    const handleCreate = () => {
        post(route('app.customers.store'), {
            onSuccess: () => {
                toastSuccess('Cliente salvo', 'Cadastro realizado com sucesso');
                reset();
            },
        });
    };

    const handleUpdate = () => {
        put(route('app.customers.update', initialData!.id), {
            onSuccess: () => {
                toastSuccess('Cliente alterado', 'Edição realizada com sucesso');
            },
        });
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (isEdit) {
            handleUpdate();
        } else {
            handleCreate();
        }
    };

    const { isZipcodeLoading } = useZipcodeAutocomplete<Customer>({
        zipcode: zipcodeToSearch || '',
        paths: {
            zipcode: 'zipcode',
            state: 'state',
            city: 'city',
            district: 'district',
            street: 'street',
            complement: 'complement',
        },
        setData: setData as any,
        setError,
        clearErrors,
    } as any);

    useEffect(() => {
        const cpfcnpj = unMask(data.cpfcnpj) ?? '';
        const phone = unMask(data.phone) ?? '';
        const whatsapp = unMask(data.whatsapp) ?? '';
        const email = String(data.email ?? '').trim();

        if (!cpfcnpj && !phone && !whatsapp && !email) {
            setDuplicateCustomers([]);
            return;
        }

        const timeout = window.setTimeout(() => {
            const params = new URLSearchParams({
                cpfcnpj,
                phone,
                whatsapp,
                email,
                ...(initialData?.id ? { exclude_id: String(initialData.id) } : {}),
            });

            fetch(`${route('app.customers.duplicate-check')}?${params.toString()}`, {
                headers: { Accept: 'application/json' },
                credentials: 'same-origin',
            })
                .then((response) => (response.ok ? response.json() : Promise.reject()))
                .then((response) => setDuplicateCustomers(response.matches ?? []))
                .catch(() => setDuplicateCustomers([]));
        }, 450);

        return () => window.clearTimeout(timeout);
    }, [data.cpfcnpj, data.phone, data.whatsapp, data.email, initialData?.id]);

    return (
        <form onSubmit={handleSubmit} autoComplete="off" className="space-y-8">
            {duplicateCustomers.length > 0 && (
                <div className="flex flex-col gap-3 rounded-lg border border-amber-200 bg-amber-50/80 px-4 py-3 text-amber-950 md:flex-row md:items-center md:justify-between dark:border-amber-900 dark:bg-amber-950/20 dark:text-amber-100">
                    <div className="flex items-start gap-2">
                        <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                        <div>
                            <p className="text-sm font-medium">Possível cliente já cadastrado</p>
                            <p className="mt-1 text-xs opacity-80">Confira documento ou contato antes de salvar. O aviso não bloqueia o cadastro.</p>
                        </div>
                    </div>
                    <div className="flex flex-wrap gap-2">
                        {duplicateCustomers.map((customer) => (
                            <Button key={customer.id} type="button" size="sm" variant="outline" asChild>
                                <a href={route('app.customers.edit', customer.id)}>
                                    #{customer.customer_number} · {customer.name}
                                </a>
                            </Button>
                        ))}
                    </div>
                </div>
            )}
            <Card>
                <CardTitle className="border-b px-6 pb-4">Dados principais</CardTitle>
                <CardContent className="pt-6">
                    <div className="grid gap-4 md:grid-cols-6">
                        <div className="grid gap-2">
                            <Label htmlFor="cpfcnpj">CPF/CNPJ</Label>
                            <Input
                                type="text"
                                id="cpfcnpj"
                                value={maskCpfCnpj(data.cpfcnpj)}
                                onChange={(e) => setData('cpfcnpj', unMask(e.target.value) ?? '')}
                                maxLength={18}
                            />
                            {errors.cpfcnpj && <div className="text-sm text-red-500">{errors.cpfcnpj}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="birth">Nascimento</Label>
                            <DatePicker
                                mode="single"
                                date={data.birth}
                                setDate={(value) => {
                                    if (!value) {
                                        setData('birth', '');
                                        return;
                                    }
                                    const d = value as Date;
                                    const formatted = [
                                        d.getFullYear(),
                                        String(d.getMonth() + 1).padStart(2, '0'),
                                        String(d.getDate()).padStart(2, '0'),
                                    ].join('-');

                                    setData('birth', formatted);
                                }}
                            />
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="name">Nome</Label>
                            <Input type="text" id="name" value={data.name} onChange={(e) => setData('name', e.target.value)} />
                            {errors.name && <div className="text-sm text-red-500">{errors.name}</div>}
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="email">E-mail</Label>
                            <Input type="email" id="email" value={data.email} onChange={(e) => setData('email', e.target.value)} />
                            {errors.email && <div className="text-sm text-red-500">{errors.email}</div>}
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardTitle className="border-b px-6 pb-4">Endereço</CardTitle>
                <CardContent className="space-y-4 pt-6">
                    <div className="grid gap-4 md:grid-cols-6">
                        <div className="grid gap-2">
                            <Label htmlFor="zipcode">CEP</Label>
                            <div className="relative flex gap-2">
                                <div className="relative w-full">
                                    <Input
                                        type="text"
                                        id="zipcode"
                                        value={maskCep(data.zipcode || '')}
                                        onChange={(e) => {
                                            const val = unMask(e.target.value) ?? '';
                                            setData('zipcode', val);
                                            clearErrors('zipcode' as any);

                                            // Dispara busca ao completar 8 dígitos, caso contrário reseta o gatilho
                                            if (val.length === 8) {
                                                setZipcodeToSearch(val);
                                            } else if (zipcodeToSearch !== null) {
                                                setZipcodeToSearch(null);
                                            }
                                        }}
                                        maxLength={9}
                                        disabled={isZipcodeLoading}
                                    />
                                    {isZipcodeLoading && (
                                        <Loader2Icon className="text-muted-foreground absolute top-1/2 right-3 h-4 w-4 -translate-y-1/2 animate-spin" />
                                    )}
                                </div>
                                <Button
                                    type="button"
                                    size="icon"
                                    variant="outline"
                                    onClick={() => {
                                        const val = unMask(data.zipcode) ?? '';
                                        if (val.length === 8) {
                                            // Forçamos o reset para garantir que o hook dispare a busca novamente
                                            setZipcodeToSearch(null);
                                            setTimeout(() => setZipcodeToSearch(val), 50);
                                        }
                                    }}
                                    disabled={isZipcodeLoading || unMask(data.zipcode)?.length !== 8}
                                >
                                    <Search className="h-4 w-4" />
                                </Button>
                            </div>
                            {errors.zipcode && <div className="text-sm text-red-500">{errors.zipcode}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="state">UF</Label>
                            <Input type="text" id="state" value={data.state} onChange={(e) => setData('state', e.target.value)} />
                            {errors.state && <div className="text-sm text-red-500">{errors.state}</div>}
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="city">Cidade</Label>
                            <Input type="text" id="city" value={data.city} onChange={(e) => setData('city', e.target.value)} />
                            {errors.city && <div className="text-sm text-red-500">{errors.city}</div>}
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="district">Bairro</Label>
                            <Input type="text" id="district" value={data.district} onChange={(e) => setData('district', e.target.value)} />
                            {errors.district && <div className="text-sm text-red-500">{errors.district}</div>}
                        </div>
                    </div>

                    <div className="grid gap-4 md:grid-cols-4">
                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="street">Endereço</Label>
                            <Input type="text" id="street" value={data.street} onChange={(e) => setData('street', e.target.value)} />
                            {errors.street && <div className="text-sm text-red-500">{errors.street}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="complement">Complemento</Label>
                            <Input type="text" id="complement" value={data.complement} onChange={(e) => setData('complement', e.target.value)} />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="number">Número</Label>
                            <Input type="text" id="number" value={data.number ?? ''} onChange={(e) => setData('number', e.target.value)} />
                            {errors.number && <div className="text-sm text-red-500">{errors.number}</div>}
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardTitle className="border-b px-6 pb-4">Contato</CardTitle>
                <CardContent className="pt-6">
                    <div className="grid gap-4 md:grid-cols-5">
                        <div className="grid gap-2">
                            <Label htmlFor="phone">Telefone</Label>
                            <Input
                                type="text"
                                id="phone"
                                value={maskPhone(data.phone)}
                                onChange={(e) => setData('phone', unMask(e.target.value) ?? '')}
                                maxLength={15}
                            />
                            {errors.phone && <div className="text-sm text-red-500">{errors.phone}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="whatsapp">Whatsapp</Label>
                            <Input
                                type="text"
                                id="whatsapp"
                                value={maskPhone(data.whatsapp)}
                                onChange={(e) => setData('whatsapp', unMask(e.target.value) ?? '')}
                                maxLength={15}
                            />
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="contactname">Contato</Label>
                            <Input type="text" id="contactname" value={data.contactname} onChange={(e) => setData('contactname', e.target.value)} />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="contactphone">Telefone do contato</Label>
                            <Input
                                type="text"
                                id="contactphone"
                                value={maskPhone(data.contactphone)}
                                onChange={(e) => setData('contactphone', unMask(e.target.value) ?? '')}
                                maxLength={15}
                            />
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardTitle className="border-b px-6 pb-4">Observações</CardTitle>
                <CardContent className="pt-6">
                    <div className="grid gap-2">
                        <Label htmlFor="observations">Observações</Label>
                        <Textarea id="observations" value={data.observations} onChange={(e) => setData('observations', e.target.value)} />
                    </div>
                </CardContent>
            </Card>

            <div className="flex justify-end">
                <Button type="submit" disabled={processing}>
                    <Save />
                    Salvar
                </Button>
            </div>
        </form>
    );
}

import AppPagination, { PaginationSummary } from '@/components/app-pagination';
import { Icon } from '@/components/icon';
import InputSearch from '@/components/inputSearch';
import {
    AlertDialog,
    AlertDialogAction,
    AlertDialogCancel,
    AlertDialogContent,
    AlertDialogDescription,
    AlertDialogFooter,
    AlertDialogHeader,
    AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuSeparator, DropdownMenuTrigger } from '@/components/ui/dropdown-menu';
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableFooter, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { buildMessage } from '@/components/WhatsAppButtonProps';
