            href: route('app.orders.index', { status: 3 }),
            icon: AlertTriangle,
            urgent: true,
        },
        {
            label: 'Aguardando retirada',
            value: Number(acount?.numorde_awaiting_pickup ?? 0),
            href: route('app.orders.index', { filter: 'awaiting_pickup' }),
            icon: Check,
        },
        {
            label: 'Sem técnico',
            value: Number(acount?.numorde_unassigned ?? 0),
