                                <Badge variant="secondary" className="bg-rose-100 text-rose-900 hover:bg-rose-100">
                                    Reprovados: {summary?.commercial?.budget?.rejected ?? 0}
                                </Badge>
                                <Badge variant="secondary" className="bg-amber-100 text-amber-900 hover:bg-amber-100">
                                    Pendentes: {summary?.commercial?.budget?.pending ?? 0}
                                </Badge>
                            </div>
                        </CardContent>
                    </Card>

                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Pagamento após contato</CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-2">
                            <div className="text-3xl font-bold">{summary?.commercial?.payment?.rate ?? 0}%</div>
                            <div className="text-muted-foreground text-sm">
                                {summary?.commercial?.payment?.recovered ?? 0} recuperadas de {summary?.commercial?.payment?.contacted ?? 0}{' '}
                                contato(s)
                            </div>
                            <div className="flex flex-wrap gap-2 pt-1">
                                <Badge variant="secondary" className="bg-emerald-100 text-emerald-900 hover:bg-emerald-100">
                                    Recuperadas: {summary?.commercial?.payment?.recovered ?? 0}
                                </Badge>
                                <Badge variant="secondary" className="bg-amber-100 text-amber-900 hover:bg-amber-100">
                                    Em aberto: {summary?.commercial?.payment?.open ?? 0}
                                </Badge>
                            </div>
                        </CardContent>
                    </Card>
                </div>

                <div className="mt-4 grid gap-4 xl:grid-cols-2">
                    <ChartFollowUpTrend
                        title="Evolução da aprovação de orçamento"
                        description="Mostra se os contatos feitos sobre orçamento parado estão ajudando a gerar aprovação."
                        trend={trends?.budget}
                    />
                    <ChartFollowUpTrend
                        title="Evolução de pagamento após cobrança"
                        description="Mostra se os contatos de cobrança estão ajudando a receber saldos pendentes."
                        trend={trends?.payment}
                    />
                </div>

                <div className="mt-4 rounded-lg border p-4">
                    <div className="mb-4 flex items-center gap-2">
                        <Filter className="h-4 w-4" />
                        <span className="text-sm font-medium">Filtros operacionais</span>
                    </div>
                    <div className="grid gap-3 xl:grid-cols-4">
                        <form onSubmit={handleSearchSubmit} className="flex gap-2">
                            <Input
                                value={search}
                                onChange={(e) => setSearch(e.target.value)}
                                placeholder="Buscar por ordem ou cliente"
                                autoComplete="off"
                            />
                            <Button type="submit" size="icon">
                                <Search className="h-4 w-4" />
                            </Button>
                        </form>

                        <div className="space-y-2 xl:space-y-0">
                            <div className="flex flex-col gap-2 xl:flex-row xl:items-center">
                                <Label className="xl:min-w-14">Tipo</Label>
                                <Select
                                    value={activeType}
                                    onValueChange={(value) =>
                                        applyFilters({
                                            type: value,
                                            search,
                                            technician_id: filters?.technician_id,
                                            response_status: filters?.response_status,
                                        })
                                    }
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Tipo" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="all">Todos</SelectItem>
                                        <SelectItem value="budget">Somente orçamento</SelectItem>
                                        <SelectItem value="payment">Somente cobrança</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        <div className="space-y-2 xl:space-y-0">
                            <div className="flex flex-col gap-2 xl:flex-row xl:items-center">
                                <Label className="xl:min-w-24">Técnico da OS</Label>
                                <Select
                                    value={filters?.technician_id ? String(filters.technician_id) : 'all'}
                                    onValueChange={(value) =>
                                        applyFilters({
                                            technician_id: value === 'all' ? undefined : value,
                                            search,
                                            type: activeType,
                                            response_status: filters?.response_status,
                                        })
                                    }
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Todos" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="all">Todos</SelectItem>
                                        {technicians?.map((technician: any) => (
                                            <SelectItem key={technician.id} value={String(technician.id)}>
                                                {technician.name}
                                            </SelectItem>
                                        ))}
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>

                        <div className="space-y-2 xl:space-y-0">
                            <div className="flex flex-col gap-2 xl:flex-row xl:items-center">
                                <Label className="xl:min-w-14">Retorno</Label>
                                <Select
                                    value={responseStatus}
                                    onValueChange={(value) =>
                                        applyFilters({
                                            response_status: value,
                                            search,
                                            technician_id: filters?.technician_id,
                                            type: activeType,
                                        })
                                    }
                                >
                                    <SelectTrigger>
                                        <SelectValue placeholder="Todos" />
                                    </SelectTrigger>
                                    <SelectContent>
                                        <SelectItem value="all">Todos</SelectItem>
                                        <SelectItem value="none">Sem retorno registrado</SelectItem>
                                        <SelectItem value="responded">Cliente respondeu</SelectItem>
                                        <SelectItem value="no_interest">Sem interesse</SelectItem>
                                        <SelectItem value="waiting_piece">Aguardando peça</SelectItem>
                                        <SelectItem value="promised_payment">Prometeu pagar</SelectItem>
                                    </SelectContent>
                                </Select>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="mt-4 space-y-4">
                    {activeType !== 'payment' && (
                        <FollowUpTable
                            title="Orçamento parado"
                            description={
                                <>
                                    Ordens com orçamento gerado e sem retorno dentro da janela configurada ({summary?.cooldown_days ?? 0} dia
                                    {(summary?.cooldown_days ?? 0) === 1 ? '' : 's'}).{' '}
                                    {canManageOtherSettings ? (
                                        <Link
                                            href={`${route('app.other-settings.index')}?tab=operational#intervalo-follow-up-cliente`}
                                            className="text-primary font-medium underline-offset-4 hover:underline"
                                        >
                                            Alterar janela
                                        </Link>
                                    ) : (
                                        <span>Alteração disponível em Outras configurações para usuários autorizados.</span>
                                    )}{' '}
                                    {!summary?.automatic_follow_ups_enabled && <span>O envio automático está desligado.</span>}
                                </>
                            }
                            orders={budgetOrders}
                            type="budget"
                            canManageOrders={canManageOrders}
                            automaticFollowUpsEnabled={Boolean(summary?.automatic_follow_ups_enabled)}
                        />
                    )}
                    {activeType !== 'budget' && (
                        <FollowUpTable
                            title="Cobrança pendente"
                            description="Ordens com saldo em aberto após a janela configurada para contato."
                            orders={paymentOrders}
                            type="payment"
                            canManageOrders={canManageOrders}
                            automaticFollowUpsEnabled={Boolean(summary?.automatic_follow_ups_enabled)}
                        />
                    )}
                </div>
            </div>
        </AppLayout>
    );
}

import { Icon } from '@/components/icon';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Checkbox } from '@/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import AppLayout from '@/layouts/app-layout';
import { BreadcrumbItem } from '@/types';
import { Head, Link, router, usePage } from '@inertiajs/react';
import { CircleCheckBig, ClipboardList, Clock3, Star, UserPlus, Wrench } from 'lucide-react';
import { useMemo, useState } from 'react';
import FollowUpTabs from './follow-up-tabs';

const breadcrumbs: BreadcrumbItem[] = [
    { title: 'Painel', href: route('app.dashboard') },
    { title: 'Central de pendências', href: route('app.follow-ups.tasks') },
];

export default function FollowUpTasks({ filters, summary, dailyAgenda, technicians }: any) {
    const { auth } = usePage<{ auth?: { user?: { id?: number }; role?: string; permissions?: string[] } }>().props;
    const canManageOrders = Boolean(auth?.role !== 'technician' && auth?.permissions?.includes('orders'));
    const currentUserId = auth?.user?.id;
    const [selectedTasks, setSelectedTasks] = useState<string[]>([]);
    const selectedCount = selectedTasks.length;

    const applyFilters = (next: Record<string, string>) => {
        router.get(
            route('app.follow-ups.tasks'),
            {
                type: next.type ?? filters?.type ?? 'all',
                priority: next.priority ?? filters?.priority ?? 'all',
                sort: next.sort ?? filters?.sort ?? 'priority',
                assigned_to: next.assigned_to ?? filters?.assigned_to ?? 'all',
            },
            {
                preserveState: true,
                replace: true,
            },
        );
    };

    const handleCompleteTask = (orderId: number, scope: 'budget' | 'payment' | 'feedback') => {
        const reason = window.prompt('Informe o motivo da conclusão desta tarefa:');

        if (!reason || !reason.trim()) {
            return;
        }

        router.post(
            route('app.follow-ups.complete-task', orderId),
            {
                scope,
                reason: reason.trim(),
            },
            {
                preserveScroll: true,
                preserveState: true,
            },
        );
    };

    const handleSnoozeTask = (orderId: number, scope: 'budget' | 'payment') => {
        const choice = window.prompt('Adiar por quantos dias? (1 a 30)', '2');
        const days = choice ? Number(choice) : NaN;

        if (!Number.isInteger(days) || days < 1 || days > 30) {
            return;
        }

        router.post(
            route('app.follow-ups.snooze-task', orderId),
            { scope, days },
            {
                preserveScroll: true,
                preserveState: true,
            },
        );
    };

    const handleAssignTask = (orderId: number, scope: 'budget' | 'payment' | 'feedback', userId: string) => {
        router.post(
            route('app.follow-ups.assign-task', orderId),
            {
                scope,
                user_id: userId === 'unassigned' ? null : Number(userId),
            },
            {
                preserveScroll: true,
                preserveState: true,
            },
        );
    };

    const handleClaimTask = (orderId: number, scope: 'budget' | 'payment' | 'feedback') => {
        if (!currentUserId) {
            return;
        }

        handleAssignTask(orderId, scope, String(currentUserId));
    };

    const taskKey = (item: any) => `${item.id}:${item.scope}`;

    const selectedTaskPayload = useMemo(
        () => dailyAgenda.filter((item: any) => selectedTasks.includes(taskKey(item))).map((item: any) => ({ order_id: item.id, scope: item.scope })),
        [dailyAgenda, selectedTasks],
    );

    const toggleTask = (item: any, checked: boolean) => {
        const key = taskKey(item);
        setSelectedTasks((current) => (checked ? [...new Set([...current, key])] : current.filter((value) => value !== key)));
    };

    const toggleAll = (checked: boolean) => {
        setSelectedTasks(checked ? dailyAgenda.map((item: any) => taskKey(item)) : []);
    };

    const handleBulkAssignToMe = () => {
        if (!currentUserId || selectedTaskPayload.length === 0) {
            return;
        }

        router.post(
            route('app.follow-ups.assign-selected'),
            {
                user_id: currentUserId,
                tasks: selectedTaskPayload,
            },
            {
                preserveScroll: true,
                preserveState: true,
                onSuccess: () => setSelectedTasks([]),
            },
        );
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="Central de pendências" />

            <div className="flex min-h-20 items-center justify-between gap-4 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={ClipboardList} className="h-8 w-8" />
                    <div>
                        <h2 className="text-xl font-semibold tracking-tight">Central de pendências</h2>
                        <p className="text-muted-foreground text-sm">Fila ativa de contatos, cobranças e tratativas que precisam de ação agora.</p>
                    </div>
                </div>
            </div>

            <FollowUpTabs />

            <div className="space-y-4 p-4">
                <div className="rounded-md border border-blue-200 bg-blue-50 p-3 text-sm text-blue-950 dark:border-blue-500/30 dark:bg-blue-950/20 dark:text-blue-100">
                    Ao concluir uma tarefa ou enviar contato, ela sai da fila pelo prazo configurado. Ela volta somente se o orçamento, pagamento ou
                    retorno continuar pendente depois desse período. Em feedback, concluir resolve a tratativa.
                </div>

                <Card>
                    <CardHeader>
                        <CardTitle className="text-base">Filtros operacionais</CardTitle>
                    </CardHeader>
                    <CardContent className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">
                        <div className="space-y-2">
                            <span className="text-sm font-medium">Tipo</span>
                            <Select value={filters?.type ?? 'all'} onValueChange={(value) => applyFilters({ type: value })}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Todos" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Todos</SelectItem>
                                    <SelectItem value="budget">Orçamento</SelectItem>
                                    <SelectItem value="payment">Cobrança</SelectItem>
                                    <SelectItem value="feedback">Cliente insatisfeito</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <span className="text-sm font-medium">Prioridade</span>
                            <Select value={filters?.priority ?? 'all'} onValueChange={(value) => applyFilters({ priority: value })}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Todas" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Todas</SelectItem>
                                    <SelectItem value="critica">Somente críticas</SelectItem>
                                    <SelectItem value="alta">Somente altas</SelectItem>
                                    <SelectItem value="normal">Somente normais</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <span className="text-sm font-medium">Responsável pelo contato</span>
                            <Select value={filters?.assigned_to ?? 'all'} onValueChange={(value) => applyFilters({ assigned_to: value })}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Todos" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="all">Todos</SelectItem>
                                    <SelectItem value="unassigned">Sem responsável pelo contato</SelectItem>
                                    {technicians?.map((technician: any) => (
                                        <SelectItem key={`filter-${technician.id}`} value={String(technician.id)}>
                                            {technician.name}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                        </div>
                        <div className="space-y-2">
                            <span className="text-sm font-medium">Ordenação</span>
                            <Select value={filters?.sort ?? 'priority'} onValueChange={(value) => applyFilters({ sort: value })}>
                                <SelectTrigger>
                                    <SelectValue placeholder="Prioridade" />
                                </SelectTrigger>
                                <SelectContent>
                                    <SelectItem value="priority">Prioridade e dias</SelectItem>
                                    <SelectItem value="days">Mais tempo sem retorno</SelectItem>
                                </SelectContent>
                            </Select>
                        </div>
                    </CardContent>
                </Card>

                <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-6">
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Pendências abertas</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.today_tasks ?? 0}</CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Orçamento</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.budget_tasks ?? 0}</CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Cobrança</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.payment_tasks ?? 0}</CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Clientes insatisfeitos</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.feedback_tasks ?? 0}</CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Sem responsável</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.unassigned_tasks ?? 0}</CardContent>
                    </Card>
                    <Card>
                        <CardHeader>
                            <CardTitle className="text-base">Críticas</CardTitle>
                        </CardHeader>
                        <CardContent className="text-3xl font-bold">{summary?.critical_tasks ?? 0}</CardContent>
                    </Card>
                </div>

                <Card>
                    <CardHeader>
                        <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
                            <CardTitle className="text-base">Lista do que precisa ser feito</CardTitle>
                            {canManageOrders && (
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={handleBulkAssignToMe}
                                    disabled={selectedCount === 0 || !currentUserId}
                                >
                                    <UserPlus className="h-4 w-4" />
                                    Assumir selecionadas{selectedCount > 0 ? ` (${selectedCount})` : ''}
                                </Button>
                            )}
                        </div>
                    </CardHeader>
                    <CardContent>
                        {!dailyAgenda?.length ? (
                            <p className="text-muted-foreground text-sm">Nenhum contato ou tratativa prioritária no momento.</p>
                        ) : (
                            <div className="max-h-[620px] overflow-auto rounded-lg border">
                                <Table>
                                    <TableHeader>
                                        <TableRow>
                                            <TableHead className="w-10">
                                                {canManageOrders && (
                                                    <Checkbox
                                                        checked={selectedCount > 0 && selectedCount === dailyAgenda.length}
                                                        onCheckedChange={(checked) => toggleAll(Boolean(checked))}
                                                        aria-label="Selecionar todas as tarefas"
                                                    />
                                                )}
                                            </TableHead>
                                            <TableHead>#</TableHead>
                                            <TableHead>Cliente</TableHead>
                                            <TableHead>Técnico da OS</TableHead>
                                            <TableHead>Responsável pelo contato</TableHead>
                                            <TableHead>Tipo</TableHead>
                                            <TableHead>Dias</TableHead>
                                            <TableHead>Próxima ação</TableHead>
                                            <TableHead className="text-right">Ações</TableHead>
                                        </TableRow>
                                    </TableHeader>
                                    <TableBody>
                                        {dailyAgenda.map((item: any) => (
                                            <TableRow
                                                key={`${item.scope}-${item.id}`}
                                                className={item.assigned_to_id ? undefined : 'bg-amber-50/70 dark:bg-amber-950/10'}
                                            >
                                                <TableCell>
                                                    {canManageOrders && (
                                                        <Checkbox
                                                            checked={selectedTasks.includes(taskKey(item))}
                                                            onCheckedChange={(checked) => toggleTask(item, Boolean(checked))}
                                                            aria-label={`Selecionar tarefa ${item.order_number}`}
                                                        />
                                                    )}
                                                </TableCell>
                                                <TableCell>{item.order_number}</TableCell>
                                                <TableCell>{item.customer}</TableCell>
                                                <TableCell>{item.technician}</TableCell>
                                                <TableCell className="min-w-[190px]">
                                                    {canManageOrders ? (
                                                        <Select
                                                            value={item.assigned_to_id ? String(item.assigned_to_id) : 'unassigned'}
                                                            onValueChange={(value) => handleAssignTask(item.id, item.scope, value)}
                                                        >
                                                            <SelectTrigger className="w-full">
                                                                <SelectValue placeholder="Definir responsável pelo acompanhamento" />
                                                            </SelectTrigger>
                                                            <SelectContent>
                                                                <SelectItem value="unassigned">Sem responsável pelo contato</SelectItem>
                                                                {technicians?.map((technician: any) => (
                                                                    <SelectItem key={`task-${technician.id}`} value={String(technician.id)}>
                                                                        {technician.name}
                                                                    </SelectItem>
                                                                ))}
                                                            </SelectContent>
                                                        </Select>
                                                    ) : (
                                                        <span className="text-sm">{item.assigned_to ?? 'Sem responsável pelo contato'}</span>
                                                    )}
                                                </TableCell>
                                                <TableCell className="capitalize">
                                                    <div className="flex items-center gap-2">
                                                        {item.scope === 'feedback' ? <Star className="h-4 w-4 text-rose-500" /> : null}
                                                        <span>{item.type}</span>
                                                        {item.scope === 'feedback' && item.rating ? (
                                                            <Badge variant="destructive">Nota {item.rating}</Badge>
                                                        ) : null}
                                                    </div>
                                                </TableCell>
                                                <TableCell>{item.days_pending}</TableCell>
                                                <TableCell>
                                                    <div className="flex items-center gap-2">
                                                        <span>{item.next_action?.label}</span>
                                                        <Badge
                                                            variant="secondary"
                                                            className={
                                                                item.next_action?.priority === 'critica'
                                                                    ? 'bg-rose-100 text-rose-900 hover:bg-rose-100'
                                                                    : item.next_action?.priority === 'alta'
                                                                      ? 'bg-amber-100 text-amber-900 hover:bg-amber-100'
                                                                      : 'bg-blue-100 text-blue-900 hover:bg-blue-100'
                                                            }
                                                        >
                                                            {item.next_action?.priority === 'critica'
                                                                ? 'Crítica'
                                                                : item.next_action?.priority === 'alta'
                                                                  ? 'Alta'
                                                                  : 'Normal'}
                                                        </Badge>
                                                    </div>
                                                </TableCell>
                                                <TableCell className="text-right">
                                                    <div className="flex justify-end gap-2">
                                                        {canManageOrders && (
                                                            <>
                                                                {!item.assigned_to_id && currentUserId && (
                                                                    <Button
                                                                        type="button"
                                                                        size="icon"
                                                                        variant="outline"
                                                                        title="Assumir tarefa"
                                                                        onClick={() => handleClaimTask(item.id, item.scope)}
                                                                    >
                                                                        <UserPlus className="h-4 w-4" />
                                                                    </Button>
                                                                )}
                                                                <Button
                                                                    type="button"
                                                                    size="icon"
                                                                    variant="outline"
                                                                    title="Concluir tarefa do dia"
                                                                    onClick={() => handleCompleteTask(item.id, item.scope)}
                                                                >
                                                                    <CircleCheckBig className="h-4 w-4" />
                                                                </Button>
                                                                {item.scope !== 'feedback' && (
                                                                    <Button
                                                                        type="button"
                                                                        size="icon"
                                                                        variant="outline"
                                                                        title="Adiar tarefa"
                                                                        onClick={() => handleSnoozeTask(item.id, item.scope)}
                                                                    >
                                                                        <Clock3 className="h-4 w-4" />
                                                                    </Button>
                                                                )}
                                                            </>
                                                        )}
                                                        {item.scope === 'feedback' ? (
                                                            <Button asChild size="icon" variant="outline" title="Abrir tratativa">
                                                                <Link href={route('app.quality.index')}>
                                                                    <Star className="h-4 w-4" />
                                                                </Link>
                                                            </Button>
                                                        ) : (
                                                            <Button asChild size="icon" variant="outline" title="Abrir ordem">
                                                                <Link href={route('app.orders.edit', item.id)}>
                                                                    <Wrench className="h-4 w-4" />
                                                                </Link>
                                                            </Button>
                                                        )}
                                                    </div>
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>
        </AppLayout>
    );
}

import AlertSuccess from '@/components/app-alert-success';
import { Icon } from '@/components/icon';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Switch } from '@/components/ui/switch';
import AppLayout from '@/layouts/app-layout';
import { BreadcrumbItem } from '@/types';
import { Head, router, useForm, usePage } from '@inertiajs/react';
import { Barcode, Printer } from 'lucide-react';
import { useMemo } from 'react';

const breadcrumbs: BreadcrumbItem[] = [
    {
        title: 'Painel',
        href: route('app.dashboard'),
    },
    {
        title: 'Imprimir etiquetas',
        href: '#',
    },
];

export default function LabelPrinting({ nextOrderNumber, labelSettings }: any) {
    const { flash } = usePage().props as any;

    const { data, setData } = useForm({
        initialorder: nextOrderNumber ?? 1,
        pages: 1,
    });

    const computedFinalOrder = useMemo(() => {
        const initial = Number(data.initialorder) || 1;
        const pages = Math.max(1, Number(data.pages) || 1);

        return initial + pages * 96 - 1;
    }, [data.initialorder, data.pages]);

    const handleSubmit = (e: any) => {
        e.preventDefault();
        const params = new URLSearchParams({
            initialorder: String(data.initialorder),
            pages: String(data.pages),
        });

        window.open(`${route('app.label-printing.print')}?${params.toString()}`, '_blank', 'noopener,noreferrer');
    };

    const handleThermalTestPrint = () => {
        const params = new URLSearchParams({
            initialorder: String(data.initialorder),
            quantity: '1',
            format: 'thermal',
        });

        window.open(`${route('app.label-printing.print')}?${params.toString()}`, '_blank', 'noopener,noreferrer');
    };

    const handleTogglePrintButton = (checked: boolean) => {
        router.put(
            route('app.label-printing.settings'),
            {
                print_label_button_after_order_create: checked,
            },
            {
                preserveScroll: true,
                preserveState: true,
            },
        );
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            {flash.message && <AlertSuccess message={flash.message} />}
            <Head title="Impressão de etiquetas" />
            <div className="flex min-h-16 flex-col justify-center gap-1 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={Barcode} className="h-8 w-8" />
                    <h2 className="text-xl font-semibold tracking-tight">Impressão de etiquetas</h2>
                </div>
            </div>

            <div className="flex items-center justify-between p-4">
                <div></div>
            </div>

            <div className="p-4">
                <div className="space-y-6">
                    <div className="bg-card overflow-hidden rounded-xl border">
                        <div className="bg-muted/40 border-b px-6 py-5">
                            <h2 className="text-foreground text-base font-semibold">Imprimir etiquetas em A4</h2>
                            <p className="text-muted-foreground mt-1 text-sm">
                                As etiquetas usam o modelo <strong className="text-foreground">A4048 (6x16)</strong>. Consulte as configurações de
                                papel{' '}
                                <a
                                    href="https://sig.ufla.br/modulos/ajuda/etiquetas.php?op=abrir&cod_etiqueta=12"
                                    target="_blank"
                                    rel="noopener noreferrer"
                                    className="font-medium text-sky-600 underline underline-offset-4"
                                >
                                    neste guia
                                </a>
                                .
                            </p>
                        </div>

                        <form onSubmit={handleSubmit} autoComplete="off" className="space-y-6 px-6 py-6">
                            <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">
                                <div className="grid gap-2">
                                    <Label htmlFor="initialorder">Ordem inicial</Label>
                                    <Input
                                        type="number"
                                        id="initialorder"
                                        value={data.initialorder}
                                        onChange={(e) => setData('initialorder', e.target.value)}
                                        min={1}
                                    />
                                    <p className="text-muted-foreground text-xs">Sugestão automática pela próxima order_number do tenant.</p>
                                </div>

                                <div className="grid gap-2">
                                    <Label htmlFor="pages">Número de páginas</Label>
                                    <Input
                                        type="number"
                                        id="pages"
                                        value={data.pages}
                                        onChange={(e: any) => setData('pages', e.target.value)}
                                        min={1}
                                    />
                                    <p className="text-muted-foreground text-xs">Cada página gera 96 etiquetas.</p>
                                </div>

                                <div className="grid gap-2">
                                    <Label htmlFor="finalorder">Ordem final</Label>
                                    <Input readOnly type="number" id="finalorder" value={computedFinalOrder} className="bg-muted/50" />
                                    <p className="text-muted-foreground text-xs">Faixa total que será enviada para impressão.</p>
                                </div>
                            </div>

                            <div className="flex justify-end">
                                <Button type="submit" className="w-full md:w-auto">
                                    <Printer />
                                    Imprimir etiquetas
                                </Button>
                            </div>

                            <div className="bg-muted/30 text-muted-foreground grid gap-3 rounded-lg border p-4 text-sm md:grid-cols-3">
                                <div>
                                    <span className="text-foreground font-medium">Modelo:</span> A4048
                                </div>
                                <div>
                                    <span className="text-foreground font-medium">Layout:</span> 6 colunas x 16 linhas
                                </div>
                                <div>
                                    <span className="text-foreground font-medium">Total:</span> {Math.max(1, Number(data.pages) || 1) * 96} etiquetas
                                </div>
                            </div>
                        </form>
                    </div>

                    <div className="bg-card overflow-hidden rounded-xl border">
                        <div className="bg-muted/40 border-b px-6 py-5">
                            <h2 className="text-foreground text-base font-semibold">Habilitar impressão em etiquetadeira</h2>
                            <p className="text-muted-foreground mt-1 text-sm">
                                Use etiquetadeira com etiqueta <strong className="text-foreground">60 x 40 mm</strong>. Um botão imprimir etiqueta ira
                                aparecer no cadastro de ordens de serviço.
                            </p>
                        </div>

                        <div className="px-6 py-6">
                            <div className="bg-muted/25 space-y-4 rounded-lg border p-4">
                                <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between">
                                    <div className="space-y-1">
                                        <p className="text-foreground text-sm font-medium">Ativar botão de impressão rápida</p>
                                        <p className="text-muted-foreground text-sm">
                                            Quando habilitado, o cadastro da ordem exibirá um botão para imprimir etiqueta.
                                        </p>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <Switch
                                            id="print_label_button_after_order_create"
                                            checked={Boolean(labelSettings?.print_label_button_after_order_create)}
                                            onCheckedChange={handleTogglePrintButton}
                                        />
                                        <span className="text-muted-foreground text-sm">
                                            {labelSettings?.print_label_button_after_order_create ? 'Habilitado' : 'Desabilitado'}
                                        </span>
                                    </div>
                                </div>

                                <div className="flex flex-col gap-3 border-t pt-4 md:flex-row md:items-center md:justify-between">
                                    <div className="space-y-1">
                                        <p className="text-foreground text-sm font-medium">Teste de impressão 60 x 40 mm</p>
                                        <p className="text-muted-foreground text-sm">
                                            Gera uma etiqueta térmica de teste usando a ordem inicial informada acima.
                                        </p>
                                    </div>
                                    <Button type="button" variant="outline" onClick={handleThermalTestPrint} className="w-full md:w-auto">
                                        <Printer />
                                        Imprimir teste 60 x 40 mm
                                    </Button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </AppLayout>
    );
}

import { Icon } from '@/components/icon';
