};

function date(value: string | null, withTime = false) {
    return value ? moment(value).format(withTime ? 'DD/MM/YYYY HH:mm' : 'DD/MM/YYYY') : '-';
}

export default function MaintenanceContractCharges({ contract, charges, history, paymentMethods, invoiceBlocker }: Props) {
    const breadcrumbs: BreadcrumbItem[] = [
        { title: 'Painel', href: route('app.dashboard') },
        { title: 'Contratos de manutenção', href: route('app.maintenance-contracts.index') },
        { title: `Cobranças do contrato ${contract.contract_number ?? contract.id}`, href: '#' },
    ];

    const [paying, setPaying] = useState<Charge | null>(null);
    const paymentForm = useForm({ amount: '', paid_at: '', payment_method: paymentMethods[0] ?? 'pix', notes: '', request_key: '' });

    const openPayment = (charge: Charge) => {
        paymentForm.setData({
            amount: normalizeMoney(charge.balance_amount),
            paid_at: moment().format('YYYY-MM-DDTHH:mm'),
            payment_method: paymentMethods[0] ?? 'pix',
            notes: '',
            // Uma chave por confirmação: duplo clique ou reenvio não registram o pagamento duas vezes.
            request_key: crypto.randomUUID(),
        });
        paymentForm.clearErrors();
        setPaying(charge);
    };

    const submitPayment = (event: React.FormEvent) => {
        event.preventDefault();
        if (!paying) return;
        paymentForm.post(route('app.maintenance-contracts.charges.payments.store', [contract.id, paying.id]), {
            preserveScroll: true,
            onSuccess: () => setPaying(null),
        });
    };

    const reverse = (payment: Payment) => {
        const reason = window.prompt(`Motivo do estorno de ${formatBRL(payment.amount)}:`);
        if (!reason) return;
        router.post(route('app.maintenance-contracts.payments.reverse', [contract.id, payment.id]), { reason }, { preserveScroll: true });
    };

    const refresh = (invoice: Invoice) => router.post(route('app.fiscal-documents.refresh', invoice.id), {}, { preserveScroll: true });

    const send = (invoice: Invoice) => {
        if (!window.confirm(`Enviar a fatura com a NFS-e para ${contract.customer?.email ?? 'o e-mail do cliente'}? Nenhuma nova nota será emitida.`))
            return;
        router.post(route('app.maintenance-contracts.invoices.send', [contract.id, invoice.id]), {}, { preserveScroll: true });
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="Cobranças do contrato" />

            <div className="flex flex-wrap items-center justify-between gap-3 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={ReceiptText} className="h-8 w-8" />
                    <div>
                        <h2 className="text-xl font-semibold tracking-tight">
                            Contrato nº {contract.contract_number ?? contract.id} — {contract.description}
                        </h2>
                        <p className="text-muted-foreground text-sm">
                            Cliente: {contract.customer?.name ?? '-'} · e-mail {contract.customer?.email || 'não informado'} · CPF/CNPJ{' '}
                            {contract.customer?.cpfcnpj || 'não informado'}
                        </p>
                    </div>
                </div>
                <Button variant="outline" asChild>
                    <Link href={route('app.maintenance-contracts.index')}>
                        <ArrowLeft className="h-4 w-4" />
                        Voltar
                    </Link>
                </Button>
            </div>

            <div className="space-y-4 p-4">
                <div className="flex flex-wrap gap-2 text-sm">
                    <Badge variant="outline">NFS-e automática por ciclo: {contract.auto_issue_invoice ? 'ligada' : 'desligada'}</Badge>
                    <Badge variant="outline">Envio automático da fatura: {contract.auto_send_invoice ? 'ligado' : 'desligado'}</Badge>
                    <Badge variant="outline">
                        Competência: {contract.invoice_competence === 'previous_month' ? 'mês anterior ao vencimento' : 'mês do vencimento'}
                    </Badge>
                    {invoiceBlocker && <span className="text-amber-700 dark:text-amber-400">Emissão fiscal indisponível: {invoiceBlocker}</span>}
                </div>

                <Card>
                    <CardTitle className="border-b px-6 pb-4">Cobranças</CardTitle>
                    <CardContent className="overflow-x-auto pt-4">
                        <Table>
                            <TableHeader>
                                <TableRow>
                                    <TableHead>Vencimento</TableHead>
                                    <TableHead>Valor</TableHead>
                                    <TableHead>Pagamento</TableHead>
                                    <TableHead>NFS-e</TableHead>
                                    <TableHead>Envio ao cliente</TableHead>
                                </TableRow>
                            </TableHeader>
                            <TableBody>
                                {charges.length === 0 && (
                                    <TableRow>
                                        <TableCell colSpan={5} className="h-16 text-center">
                                            Nenhuma cobrança gerada ainda.
                                        </TableCell>
                                    </TableRow>
                                )}
                                {charges.map((charge) => (
                                    <ChargeRows
                                        key={charge.id}
                                        charge={charge}
                                        onPay={openPayment}
                                        onReverse={reverse}
                                        onRefresh={refresh}
                                        onSend={send}
                                    />
                                ))}
                            </TableBody>
                        </Table>
                    </CardContent>
                </Card>

                <Card>
                    <CardTitle className="border-b px-6 pb-4">Histórico financeiro e fiscal</CardTitle>
                    <CardContent className="pt-4">
                        {history.length === 0 ? (
                            <p className="text-muted-foreground text-sm">Sem registros.</p>
                        ) : (
                            <ul className="space-y-2 text-sm">
                                {history.map((entry) => (
                                    <li key={entry.id} className="flex flex-wrap justify-between gap-2 border-b pb-2 last:border-b-0">
                                        <span>
                                            <strong>{historyLabels[entry.action] ?? entry.action}</strong>
                                            {typeof entry.data?.amount === 'number' && ` · ${formatBRL(entry.data.amount as number)}`}
                                            {typeof entry.data?.number === 'string' && ` · nº ${entry.data.number}`}
                                            {typeof entry.data?.reason === 'string' && ` · ${entry.data.reason}`}
                                            {typeof entry.data?.error === 'string' && (
                                                <span className="text-destructive"> · {entry.data.error as string}</span>
                                            )}
                                        </span>
                                        <span className="text-muted-foreground">
                                            {date(entry.created_at, true)} {entry.user ? `· ${entry.user}` : '· sistema'}
                                        </span>
                                    </li>
                                ))}
                            </ul>
                        )}
                    </CardContent>
                </Card>
            </div>

            <Dialog open={!!paying} onOpenChange={(open) => (!open ? setPaying(null) : null)}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Confirmar pagamento efetuado</DialogTitle>
                    </DialogHeader>
                    <form onSubmit={submitPayment} className="space-y-4">
                        <p className="text-muted-foreground text-sm">
                            {paying?.description} · saldo {formatBRL(paying?.balance_amount ?? 0)}. O valor entra no caixa aberto.
                        </p>
                        <div className="grid gap-2">
                            <Label htmlFor="amount">Valor recebido</Label>
                            <MoneyInput
                                id="amount"
                                value={paymentForm.data.amount}
                                onValueChange={(value) => paymentForm.setData('amount', value)}
                                error={paymentForm.errors.amount}
                            />
                            <InputError message={paymentForm.errors.amount} />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="paid_at">Data do recebimento</Label>
                            <Input
                                id="paid_at"
                                type="datetime-local"
                                value={paymentForm.data.paid_at}
                                onChange={(e) => paymentForm.setData('paid_at', e.target.value)}
                            />
                            <InputError message={paymentForm.errors.paid_at} />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="payment_method">Forma de pagamento</Label>
                            <Select value={paymentForm.data.payment_method} onValueChange={(value) => paymentForm.setData('payment_method', value)}>
                                <SelectTrigger id="payment_method">
                                    <SelectValue placeholder="Selecione" />
                                </SelectTrigger>
                                <SelectContent>
                                    {paymentMethods.map((method) => (
                                        <SelectItem key={method} value={method}>
                                            {methodLabels[method] ?? method}
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                            <InputError message={paymentForm.errors.payment_method} />
                        </div>
                        <div className="grid gap-2">
                            <Label htmlFor="notes">Observações</Label>
                            <Textarea
                                id="notes"
                                rows={2}
                                value={paymentForm.data.notes}
                                onChange={(e) => paymentForm.setData('notes', e.target.value)}
                            />
                        </div>
                        <DialogFooter>
                            <Button type="button" variant="outline" onClick={() => setPaying(null)}>
                                Cancelar
                            </Button>
                            <Button type="submit" disabled={paymentForm.processing}>
                                Confirmar pagamento
                            </Button>
                        </DialogFooter>
                    </form>
                </DialogContent>
            </Dialog>
        </AppLayout>
    );
}

type RowProps = {
    charge: Charge;
    onPay: (charge: Charge) => void;
    onReverse: (payment: Payment) => void;
    onRefresh: (invoice: Invoice) => void;
    onSend: (invoice: Invoice) => void;
};

function ChargeRows({ charge, onPay, onReverse, onRefresh, onSend }: RowProps) {
    const invoice = charge.invoice;
    const delivery = invoice?.delivery;
    const state = charge.payment_state;

    return (
        <>
            <TableRow>
                <TableCell>{date(charge.due_date)}</TableCell>
                <TableCell>{formatBRL(charge.total_amount)}</TableCell>
                <TableCell>
                    {/* Pagamento e situação fiscal ficam em colunas separadas. */}
                    <div className="grid justify-items-start gap-1 text-sm">
                        {state === 'paid' && (
                            <Badge
                                variant="outline"
                                className="gap-1 border-emerald-300 bg-emerald-100 text-emerald-800 dark:border-emerald-800 dark:bg-emerald-950/40 dark:text-emerald-300"
                            >
                                <CheckCircle2 className="h-3.5 w-3.5" />
                                Pago
                            </Badge>
                        )}
                        {state === 'cancelled' && (
                            <Badge variant="outline" className="bg-muted text-muted-foreground">
                                Cancelada
                            </Badge>
                        )}
                        {state === 'awaiting_automatic' && (
                            <Badge variant="outline" title={charge.automatic_channel ?? undefined}>
                                Aguardando pagamento
                            </Badge>
                        )}
                        {(state === 'pay' || state === 'pay_balance') && (
                            <Button size="sm" onClick={() => onPay(charge)}>
                                <Wallet className="h-4 w-4" />
                                {state === 'pay_balance' ? 'Parcial — Pagar saldo' : 'Pagar'}
                            </Button>
                        )}
                        {charge.overdue && (
                            <Badge
                                variant="outline"
                                className="border-red-300 bg-red-50 text-red-700 dark:border-red-900 dark:bg-red-950/40 dark:text-red-300"
                            >
                                Vencida
                            </Badge>
                        )}
                        {charge.status === 'paid' && charge.last_paid_at && (
                            <span className="text-muted-foreground text-xs">em {date(charge.last_paid_at)}</span>
                        )}
                        {(charge.status === 'partial' || state === 'awaiting_automatic') && charge.paid_amount > 0 && (
                            <span className="text-muted-foreground text-xs">
                                Recebido {formatBRL(charge.paid_amount)} · saldo {formatBRL(charge.balance_amount)}
                            </span>
                        )}
                    </div>
                </TableCell>
                <TableCell className="text-sm">
                    <div className="grid justify-items-start gap-1">
                        {charge.competence && <span className="text-muted-foreground text-xs">Competência {charge.competence}</span>}
                        {invoice ? (
                            <>
                                <span className="font-medium">{invoiceStatus[invoice.status] ?? invoice.status}</span>
                                {invoice.number && <span>nº {invoice.number}</span>}
                                {invoice.provider_reference && <span className="text-muted-foreground text-xs">id {invoice.provider_reference}</span>}
                                {invoice.issued_at && <span className="text-muted-foreground text-xs">autorizada em {date(invoice.issued_at)}</span>}
                                {invoice.error_message && <span className="text-destructive text-xs">{invoice.error_message}</span>}
                            </>
                        ) : charge.fiscal_state === 'scheduled' ? (
                            <span className="font-medium">
                                Programada{charge.fiscal_scheduled_for ? ` para ${date(charge.fiscal_scheduled_for)}` : ''}
                            </span>
                        ) : (
                            <span className="text-muted-foreground">Não emitida</span>
                        )}
                        <div className="flex flex-wrap gap-1">
                            {invoice?.can_refresh && (
                                <Button size="icon" variant="outline" title="Consultar status da nota" onClick={() => onRefresh(invoice)}>
                                    <RefreshCcw className="h-4 w-4" />
                                </Button>
                            )}
                            {invoice?.pdf_url && (
                                <Button size="sm" variant="outline" asChild>
                                    <a href={invoice.pdf_url} target="_blank" rel="noopener noreferrer">
                                        PDF
                                    </a>
                                </Button>
                            )}
                            {invoice?.xml_url && (
                                <Button size="sm" variant="outline" asChild>
                                    <a href={invoice.xml_url}>XML</a>
                                </Button>
                            )}
                        </div>
                    </div>
                </TableCell>
                <TableCell className="text-sm">
                    <div className="grid justify-items-start gap-1">
                        {delivery ? (
                            <>
                                <span className={delivery.status === 'sent' ? '' : 'text-destructive'}>
                                    {delivery.status === 'sent' ? 'Enviado' : 'Falhou'} ({delivery.origin === 'automatic' ? 'automático' : 'reenvio'})
                                </span>
                                <span className="text-muted-foreground text-xs">
                                    {delivery.email ?? 'sem e-mail'} · {date(delivery.created_at, true)}
                                </span>
                                {delivery.error && <span className="text-destructive text-xs">{delivery.error}</span>}
                            </>
                        ) : (
                            <span className={charge.delivery_state === 'none' ? 'text-muted-foreground' : ''}>
                                {deliveryStatus[charge.delivery_state]}
                            </span>
                        )}
                        {invoice?.can_send && (
                            <Button size="sm" variant="outline" title="Enviar a fatura com a mesma nota ao cliente" onClick={() => onSend(invoice)}>
                                <Send className="h-4 w-4" />
                                {invoice.deliveries_count > 0 ? 'Reenviar' : 'Enviar'}
                            </Button>
                        )}
                    </div>
                </TableCell>
            </TableRow>
            {charge.payments.map((payment) => (
                <TableRow key={`payment-${payment.id}`} className="bg-muted/30 text-sm">
                    <TableCell colSpan={4} className="pl-8">
                        <span className={payment.reversed_at ? 'line-through' : ''}>
                            {formatBRL(payment.amount)} em {date(payment.paid_at, true)} ·{' '}
                            {methodLabels[payment.payment_method] ?? payment.payment_method} ·{' '}
                            {payment.source === 'integration' ? 'pagamento integrado' : `confirmado por ${payment.received_by ?? '-'}`}
                        </span>
                        {payment.reversed_at && (
                            <span className="text-destructive">
                                {' '}
                                · estornado em {date(payment.reversed_at, true)} por {payment.reversed_by ?? '-'}: {payment.reversal_reason}
                            </span>
                        )}
                    </TableCell>
                    <TableCell className="text-right">
                        {!payment.reversed_at && (
                            <Button size="sm" variant="ghost" onClick={() => onReverse(payment)}>
                                <Undo2 className="h-4 w-4" />
                                Estornar
                            </Button>
                        )}
                    </TableCell>
                </TableRow>
            ))}
        </>
    );
}

import ActionDelete from '@/components/action-delete';
