import { Head, Link, router, useForm, usePage } from '@inertiajs/react';
import {
    AlertTriangle,
    Barcode,
    Camera,
    Clock3,
    Edit,
    FileTextIcon,
    ImageUp,
    LinkIcon,
    Mail,
    MoreHorizontal,
    Plus,
    Printer,
