import ActionDelete from '@/components/action-delete';
import AppPagination, { PaginationSummary } from '@/components/app-pagination';
import { normalizeScannedEan13 } from '@/components/ean13-barcode';
import { Icon } from '@/components/icon';
import InputSearch from '@/components/inputSearch';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Table, TableBody, TableCell, TableFooter, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import AppLayout from '@/layouts/app-layout';
import { formatBRL } from '@/lib/money';
import { BreadcrumbItem } from '@/types';
import { Head, Link, router, useForm, usePage } from '@inertiajs/react';
import { Barcode, Camera, Edit, PackageCheck, Plus, Printer, ShoppingCart, Upload } from 'lucide-react';
import moment from 'moment';
import { useCallback, useEffect, useRef, useState } from 'react';
import ImportPartsModal from './import-parts-modal';

declare global {
    interface Window {
        BarcodeDetector?: new (options?: { formats?: string[] }) => {
            detect: (source: CanvasImageSource) => Promise<Array<{ rawValue?: string }>>;
        };
    }
}

const breadcrumbs: BreadcrumbItem[] = [
    {
        title: 'Painel',
        href: route('app.dashboard'),
    },
    {
        title: 'Peças e produtos',
        href: '#',
    },
];

export default function Parts({ parts, search, filter }: any) {
    const { auth } = usePage<{ auth?: { permissions?: string[] } }>().props;
    const canManageParts = auth?.permissions?.includes('parts');
    const canPurchase = auth?.permissions?.includes('purchase_orders');
    const barcodeForm = useForm({
        barcode: '',
    });
    const [cameraOpen, setCameraOpen] = useState(false);
    const [importOpen, setImportOpen] = useState(false);
    const [cameraError, setCameraError] = useState<string | null>(null);
    const [cameraSupported, setCameraSupported] = useState(false);
    const [isMobileDevice, setIsMobileDevice] = useState(false);
    const videoRef = useRef<HTMLVideoElement | null>(null);
    const streamRef = useRef<MediaStream | null>(null);

    const submitBarcodeSearch = useCallback((barcode: string) => {
        const rawCode = String(barcode || '').trim();
        const code = normalizeScannedEan13(rawCode) ?? rawCode;
        if (!code) return;

        router.get(
            route('app.parts.index'),
            {
                search: code,
            },
            {
                preserveState: false,
                replace: true,
            },
        );
    }, []);

    const handleBarcodeSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        submitBarcodeSearch(barcodeForm.data.barcode);
    };

    const stopCamera = () => {
        streamRef.current?.getTracks().forEach((track) => track.stop());
        streamRef.current = null;
    };

    useEffect(() => {
        if (typeof window === 'undefined') return;

        const hasCameraApi = 'BarcodeDetector' in window && !!navigator.mediaDevices?.getUserMedia;
        const mobileByViewport = window.matchMedia('(max-width: 768px)').matches;
        const mobileByPointer = window.matchMedia('(pointer: coarse)').matches;
        const mobileByUserAgent = /Android|iPhone|iPad|iPod|Mobile/i.test(window.navigator.userAgent);

        setCameraSupported(hasCameraApi);
        setIsMobileDevice(mobileByViewport || mobileByPointer || mobileByUserAgent);
    }, []);

    useEffect(() => {
        if (!cameraOpen || !cameraSupported) return;

        let animationFrameId = 0;
        let cancelled = false;
        const detector = window.BarcodeDetector
            ? new window.BarcodeDetector({
                  formats: ['code_128', 'code_39', 'ean_13', 'ean_8', 'upc_a', 'upc_e'],
              })
            : null;

        const scan = async () => {
            if (cancelled || !detector || !videoRef.current) return;

            try {
                const barcodes = await detector.detect(videoRef.current);
                const value = barcodes.find((item) => item.rawValue)?.rawValue?.trim();

                if (value) {
                    barcodeForm.setData('barcode', value);
                    setCameraOpen(false);
                    stopCamera();
                    submitBarcodeSearch(value);
                    return;
                }
            } catch {
                // Ignora leituras intermitentes enquanto a câmera está aberta.
            }

            animationFrameId = window.requestAnimationFrame(scan);
        };

        navigator.mediaDevices
            .getUserMedia({
                video: {
                    facingMode: { ideal: 'environment' },
                },
            })
            .then((stream) => {
                if (cancelled) {
                    stream.getTracks().forEach((track) => track.stop());
                    return;
                }

                streamRef.current = stream;

                if (videoRef.current) {
                    videoRef.current.srcObject = stream;
                    videoRef.current.play().catch(() => null);
                }

                animationFrameId = window.requestAnimationFrame(scan);
            })
            .catch(() => {
                setCameraError('Não foi possível acessar a câmera deste dispositivo.');
            });

        return () => {
            cancelled = true;
            if (animationFrameId) {
                window.cancelAnimationFrame(animationFrameId);
            }
            stopCamera();
        };
    }, [cameraOpen, cameraSupported, submitBarcodeSearch]);

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title="Peças" />
            <div className="flex min-h-16 flex-col justify-center gap-1 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={PackageCheck} className="h-8 w-8" />
                    <h2 className="text-xl font-semibold tracking-tight">Peças e produtos</h2>
                </div>
            </div>
            <div className="flex flex-col gap-3 p-4 lg:flex-row lg:items-center lg:justify-between">
                <div className="flex w-full min-w-0 flex-col gap-2 lg:max-w-[790px] lg:flex-1 lg:flex-row">
                    <div className="w-full min-w-0 lg:max-w-[420px] lg:flex-1">
                        <InputSearch placeholder="Buscar peça/produto por nome, número ou código" url="app.parts.index" />
                    </div>
                    <form onSubmit={handleBarcodeSubmit} className="w-full min-w-0 lg:max-w-[360px] lg:flex-1">
                        <div className="flex gap-2">
                            {isMobileDevice ? (
                                <Button
                                    type="button"
                                    variant="outline"
                                    onClick={() => {
                                        setCameraError(null);
                                        setCameraOpen(true);
                                    }}
                                    disabled={!cameraSupported}
                                    title={
                                        cameraSupported
                                            ? 'Ler código de barras com a câmera do celular'
                                            : 'Leitura por câmera indisponível neste navegador'
                                    }
                                    className="w-full"
                                >
                                    <Camera className="mr-1 h-4 w-4" />
                                    Ler com celular
                                </Button>
                            ) : (
                                <div className="relative flex-1">
                                    <Input
                                        value={barcodeForm.data.barcode}
                                        onChange={(e) => barcodeForm.setData('barcode', e.target.value)}
                                        placeholder="Ler código de barras"
                                        autoComplete="off"
                                        className="pr-12"
                                    />
                                    <Button
                                        type="submit"
                                        size="icon"
                                        className="absolute top-0 right-0 h-full rounded-l-none"
                                        title="Buscar pelo código de barras"
                                        aria-label="Buscar pelo código de barras"
                                    >
                                        <Barcode className="h-4 w-4" />
                                    </Button>
                                </div>
                            )}
                        </div>
                    </form>
                </div>
                <div className="flex w-full flex-wrap items-center gap-2 lg:w-auto lg:shrink-0 lg:justify-end">
                    <Button variant={filter === 'low_stock' ? 'default' : 'outline'} asChild className="w-full whitespace-nowrap sm:w-auto">
                        <Link href={route('app.parts.index', { search, filter: filter === 'low_stock' ? undefined : 'low_stock' })}>
                            {filter === 'low_stock' ? 'Mostrar todos' : 'Estoque baixo'}
                        </Link>
                    </Button>
                    {canManageParts && (
                        <Button onClick={() => setImportOpen(true)} className="w-full bg-green-600 text-white hover:bg-green-700 sm:w-auto">
                            <Upload className="h-4 w-4" />
                            <span>CSV</span>
                        </Button>
                    )}
                    {canManageParts && (
                        <Button variant={'default'} asChild className="w-full whitespace-nowrap sm:w-auto">
                            <Link href={route('app.parts.create')}>
                                <Plus className="h-4 w-4" />
                                <span>Nova peça ou produto</span>
                            </Link>
                        </Button>
                    )}
                </div>
            </div>

            <ImportPartsModal isOpen={importOpen} onClose={() => setImportOpen(false)} />

            {cameraError && <div className="px-4 text-sm text-red-600">{cameraError}</div>}
            {cameraOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 p-4">
                    <div className="bg-background w-full max-w-md rounded-lg p-4 shadow-xl">
                        <div className="mb-3 flex items-center justify-between gap-3">
                            <h3 className="font-semibold">Ler código de barras</h3>
                            <Button
                                type="button"
                                variant="outline"
                                size="sm"
                                onClick={() => {
                                    setCameraOpen(false);
                                    stopCamera();
                                }}
                            >
                                Fechar
                            </Button>
                        </div>
                        <video ref={videoRef} className="aspect-video w-full rounded-md bg-black" muted playsInline />
                    </div>
                </div>
            )}

            <div className="p-4">
                <PaginationSummary data={parts} />
                <div className="rounded-lg border">
                    <Table>
                        <TableHeader>
                            <TableRow>
                                <TableHead className="min-w-max">#</TableHead>
                                <TableHead className="w-[72px]">Imagem</TableHead>
                                <TableHead>Item</TableHead>
                                <TableHead>Classificação</TableHead>
                                <TableHead>Valores</TableHead>
                                <TableHead>Estoque</TableHead>
                                <TableHead>Cadastro</TableHead>
                                <TableHead className="min-w-[140px]"></TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {parts?.data.length ? (
                                parts?.data?.map((part: any) => (
                                    <TableRow key={part.id}>
                                        <TableCell>{part.part_number}</TableCell>
                                        <TableCell>
                                            <div className="bg-muted flex h-12 w-12 items-center justify-center overflow-hidden rounded-md border">
                                                <img
                                                    src={part.image ? `/storage/parts/${part.image}` : '/images/default.png'}
                                                    alt={part.image ? `Imagem de ${part.name}` : 'Imagem padrão do produto'}
                                                    className="h-full w-full object-contain p-1"
                                                    onError={(event) => {
                                                        event.currentTarget.src = '/images/default.png';
                                                    }}
                                                />
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="space-y-1">
                                                <div className="font-medium">{part.name}</div>
                                                <div className="text-muted-foreground text-xs">Ref: {part.reference_number || '-'}</div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="space-y-1">
                                                <div>{part.type === 'part' ? 'Peça' : 'Produto'}</div>
                                                <div className="text-muted-foreground text-xs">
                                                    {part.category || 'Sem categoria'} · {part.is_sellable ? 'Vendável' : 'Uso interno'}
                                                </div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            <div className="space-y-1 text-sm">
                                                <div>Venda: {formatBRL(part.sale_price)}</div>
                                                <div className="text-muted-foreground text-xs">Mínimo: {part.minimum_stock_level}</div>
                                            </div>
                                        </TableCell>
                                        <TableCell>
                                            {part.quantity <= part.minimum_stock_level ? (
                                                <div className="space-y-1">
                                                    <Badge variant={'destructive'}>{part.quantity}</Badge>
                                                    <div className="text-muted-foreground text-xs">
                                                        Repor pelo menos {Math.max(1, Number(part.minimum_stock_level) - Number(part.quantity) + 1)}
                                                    </div>
                                                </div>
                                            ) : (
                                                <Badge variant={'default'}>{part.quantity}</Badge>
                                            )}
                                        </TableCell>
                                        <TableCell>{moment(part.created_at).format('DD/MM/YYYY')}</TableCell>

                                        <TableCell className="min-w-[140px]">
                                            <div className="flex flex-wrap justify-end gap-2">
                                                {canPurchase && part.quantity <= part.minimum_stock_level && (
                                                    <Button
                                                        asChild
                                                        size="icon"
                                                        className="bg-amber-500 text-white hover:bg-amber-600"
                                                        title="Comprar esta peça (estoque baixo)"
                                                    >
                                                        <Link
                                                            href={route('app.purchase-orders.create', { part_id: part.id })}
                                                            aria-label={`Comprar ${part.name}`}
                                                        >
                                                            <ShoppingCart className="h-4 w-4" />
                                                        </Link>
                                                    </Button>
                                                )}
                                                {canManageParts && (
                                                    <Button asChild size="icon" variant="outline" title="Imprimir etiqueta do produto">
                                                        <a
                                                            href={route('app.parts.print-label', part.id)}
                                                            target="_blank"
                                                            rel="noopener noreferrer"
                                                            aria-label={`Imprimir etiqueta de ${part.name}`}
                                                        >
                                                            <Printer className="h-4 w-4" />
                                                        </a>
                                                    </Button>
                                                )}
                                                {canManageParts && (
                                                    <Button
                                                        asChild
                                                        size="icon"
                                                        className="bg-orange-500 text-white hover:bg-orange-600"
                                                        title="Editar peça ou produto"
                                                    >
                                                        <Link
                                                            href={route('app.parts.edit', part.id)}
                                                            data={{ page: parts.current_page, search: search }}
                                                            aria-label={`Editar ${part.name}`}
                                                        >
                                                            <Edit className="h-4 w-4" />
                                                        </Link>
                                                    </Button>
                                                )}

                                                {canManageParts && <ActionDelete title={'esta peça'} url={'app.parts.destroy'} param={part.id} />}
                                            </div>
                                        </TableCell>
                                    </TableRow>
                                ))
                            ) : (
                                <TableRow>
                                    <TableCell colSpan={8} className="flex h-16 w-full items-center justify-center">
                                        Não há dados a serem mostrados no momento.
                                    </TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                        <TableFooter>
                            <TableRow>
                                <TableCell colSpan={8}>
                                    <AppPagination data={parts} />
                                </TableCell>
                            </TableRow>
                        </TableFooter>
                    </Table>
                </div>
            </div>
        </AppLayout>
    );
}

import { toastWarning } from '@/components/app-toast-messages';
import { generateEan13 } from '@/components/ean13-barcode';
import InputError from '@/components/input-error';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { MoneyInput } from '@/components/ui/money-input';
import { Switch } from '@/components/ui/switch';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { cn } from '@/lib/utils';
import { apios } from '@/Utils/connectApi';
import { partsType } from '@/Utils/dataSelect';
import { useForm } from '@inertiajs/react';
import { Barcode, Info, Save, UploadCloud } from 'lucide-react';
import { DragEvent, useEffect, useRef, useState } from 'react';

interface PartFormProps {
    categories: any;
    manufacturers: any;
    initialData?: any;
    fiscalNfeEnabled?: boolean;
}

export default function PartForm({ initialData }: PartFormProps) {
    const isEdit = !!initialData;
    const [disableInput, setDisableInput] = useState(false);
    const [isDraggingImage, setIsDraggingImage] = useState(false);
    const [imagePreview, setImagePreview] = useState<string | null>(null);
    const imageInputRef = useRef<HTMLInputElement>(null);

    const generateReferenceNumber = () => generateEan13(String(Date.now()).slice(-12));

    const { data, setData, post, progress, processing, reset, errors } = useForm({
        _method: isEdit ? 'put' : '',
        category: initialData?.category ?? '',
        type: initialData?.type ?? '',
        is_sellable: Boolean(initialData?.is_sellable ?? false),
        reference_number: initialData?.reference_number ?? '',
        name: initialData?.name ?? '',
        description: initialData?.description ?? '',
        image: null as File | null,
        ncm: initialData?.ncm ?? '',
        cfop: initialData?.cfop ?? '',
        manufacturer: initialData?.manufacturer ?? '',
        model_compatibility: initialData?.model_compatibility ?? '',
        cost_price: initialData?.cost_price ?? '',
        sale_price: initialData?.sale_price ?? '',
        quantity: initialData?.quantity ?? '',
        minimum_stock_level: initialData?.minimum_stock_level ?? '',
        location: initialData?.location ?? '',
        status: Boolean(initialData?.status ?? true),
    });

    const defaultPartsType = partsType?.filter((part: any) => Number(part.value) === initialData?.type);
    const [selectedPartsType, setSelectedPartsType] = useState<any>(defaultPartsType);
    const [insertStock, setInsertStock] = useState<any>(false);
    const currentImageSrc = initialData?.image ? `/storage/parts/${initialData.image}` : '/images/default.png';

    const handleImageFile = (file?: File) => {
        if (!file) return;

        if (!file.type.startsWith('image/')) {
            toastWarning('Erro', 'Apenas imagens são permitidas.');
            return;
        }

        if (file.size > 2 * 1024 * 1024) {
            toastWarning('Erro', 'A imagem deve ter no máximo 2 MB.');
            return;
        }

        if (imagePreview) {
            URL.revokeObjectURL(imagePreview);
        }

        setData('image', file);
        setImagePreview(URL.createObjectURL(file));
    };

    const handleImageDrop = (e: DragEvent<HTMLDivElement>) => {
        e.preventDefault();
        setIsDraggingImage(false);
        handleImageFile(e.dataTransfer.files?.[0]);
    };

    const handleSubmit = (e: any) => {
        e.preventDefault();

        if (isEdit) {
            post(route('app.parts.update', initialData.id), {
                forceFormData: true,
            });
        } else {
            post(route('app.parts.store'), {
                forceFormData: true,
            });
        }
    };

    const partNumberDataSelected = async (e: any) => {
        e.preventDefault();
        const valuePartNumber = e.target.value;

        try {
            const { data: response } = await apios.get(`getparts/${valuePartNumber}`);
            const { success, parts } = response;

            if (success && parts) {
                setDisableInput(true);
                setInsertStock(true);

                setData((data) => ({
                    ...data,
                    category: parts.category,
                    type: parts.type,
                    name: parts.name,
                    description: parts.description,
                    image: null,
                    ncm: parts.ncm ?? '',
                    cfop: parts.cfop ?? '',
                    manufacturer: parts.manufacturer,
                    model_compatibility: parts.model_compatibility,
                    cost_price: parts.cost_price,
                    sale_price: parts.sale_price,
                    quantity: '0',
                    minimum_stock_level: parts.minimum_stock_level,
                    location: parts.location,
                    status: parts.status,
                    is_sellable: Boolean(parts.is_sellable),
                }));
            } else {
                setDisableInput(false);

                reset('name', 'description', 'manufacturer', 'model_compatibility', 'quantity', 'location', 'type');
                setData((data) => ({ ...data, image: null, is_sellable: false, status: true }));
            }
        } catch (error) {
            console.error(error);
        }
    };

    useEffect(() => {
        if (!isEdit && !data.reference_number) {
            setData('reference_number', generateReferenceNumber());
        }
    }, [isEdit]);

    useEffect(() => {
        return () => {
            if (imagePreview) {
                URL.revokeObjectURL(imagePreview);
            }
        };
    }, [imagePreview]);

    return (
        <form onSubmit={handleSubmit} autoComplete="off" className="space-y-8">
            <Card>
                <CardTitle className="border-b px-6 pb-4">Identificação</CardTitle>
                <CardContent className="space-y-4 pt-6">
                    <div className="mt-4 grid gap-4 md:grid-cols-4">
                        <div className="grid gap-2">
                            <div className="flex items-center gap-2">
                                <Label htmlFor="name">Número da Peça/Produto</Label>
                                {!isEdit && (
                                    <Tooltip>
                                        <TooltipTrigger asChild>
                                            <button
                                                type="button"
                                                className="text-muted-foreground hover:text-foreground"
                                                aria-label="Informação sobre código gerado"
                                            >
                                                <Info className="h-4 w-4" />
                                            </button>
                                        </TooltipTrigger>
                                        <TooltipContent>
                                            <p>Código gerado automaticamente para uso como código de barras.</p>
                                        </TooltipContent>
                                    </Tooltip>
                                )}
                            </div>
                            <div className="flex gap-2">
                                <Input
                                    type="text"
                                    id="reference_number"
                                    value={data.reference_number}
                                    onChange={(e) => setData('reference_number', e.target.value)}
                                    onBlur={(e) => partNumberDataSelected(e)}
                                    maxLength={18}
                                />
                                {!isEdit && (
                                    <Button
                                        type="button"
                                        variant="outline"
                                        onClick={() => setData('reference_number', generateReferenceNumber())}
                                        title="Gerar código de barras"
                                    >
                                        <Barcode className="h-4 w-4" />
                                    </Button>
                                )}
                            </div>
                            {errors.reference_number && <div className="text-sm text-red-500">{errors.reference_number}</div>}
                        </div>

                        <div className="grid gap-2">
                            <div className="flex items-center justify-between">
                                <Label>Tipo</Label>

                                <span className={`text-xs ${!data.type ? 'text-amber-600' : 'text-muted-foreground'}`}>
                                    {!data.type && 'Selecione o tipo do item'}
                                    {data.type === 'part' && 'Item técnico (uso interno ou venda)'}
                                    {data.type === 'product' && 'Produto final para venda'}
                                </span>
                            </div>

                            {/* Tipo (identidade) */}
                            <div className="flex items-center justify-between gap-6 rounded-md border p-2.5">
                                <div className="flex items-center justify-between gap-4">
                                    <label className="flex cursor-pointer items-center gap-2">
                                        <input type="radio" name="type" checked={data.type === 'part'} onChange={() => setData('type', 'part')} />
                                        <span className="text-sm">Peça</span>
                                    </label>

                                    <label className="flex cursor-pointer items-center gap-2">
                                        <input
                                            type="radio"
                                            name="type"
                                            checked={data.type === 'product'}
                                            onChange={() => setData('type', 'product')}
                                        />
                                        <span className="text-sm">Produto</span>
                                    </label>
                                </div>

                                <div className="flex items-center justify-between gap-2">
                                    <span className="text-muted-foreground text-sm">Para venda</span>

                                    <Switch checked={Boolean(data.is_sellable)} onCheckedChange={(checked) => setData('is_sellable', checked)} />
                                </div>
                            </div>

                            {/* Pode ser vendido */}

                            {errors.type && <div className="text-sm text-red-500">{errors.type}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="category">Categoria</Label>
                            <Input
                                type="text"
                                id="category"
                                value={data.category}
                                onChange={(e) => setData('category', e.target.value)}
                                placeholder="Digite a categoria"
                                readOnly={disableInput}
                            />
                            <InputError message={errors.category} />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="manufacturer">Fabricante</Label>
                            <Input
                                type="text"
                                id="manufacturer"
                                value={data.manufacturer}
                                onChange={(e) => setData('manufacturer', e.target.value)}
                                placeholder="Digite o fabricante"
                                readOnly={disableInput}
                            />
                            <InputError message={errors.manufacturer} />
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardTitle className="border-b px-6 pb-4">Descrição e compatibilidade</CardTitle>
                <CardContent className="space-y-4 pt-6">
                    <div className="mt-4 grid gap-4 md:grid-cols-3">
                        <div className="grid gap-2">
                            <Label htmlFor="name">Nome da Peça/Produto</Label>
                            <Input
                                type="text"
                                id="name"
                                value={data.name}
                                onChange={(e) => setData('name', e.target.value)}
                                readOnly={disableInput}
                            />
                            {errors.name && <div className="text-sm text-red-500">{errors.name}</div>}
                        </div>

                        <div className="grid gap-2 md:col-span-2">
                            <Label htmlFor="description">Descrição</Label>
                            <Input
                                type="text"
                                id="description"
                                value={data.description}
                                onChange={(e) => setData('description', e.target.value)}
                                readOnly={disableInput}
                            />
                            {errors.description && <div className="text-sm text-red-500">{errors.description}</div>}
                        </div>
                    </div>

                    <div className="mt-4 grid gap-2">
                        <Label htmlFor="image">Imagem do produto</Label>
                        <div
                            onDragEnter={(e) => {
                                e.preventDefault();
                                if (!disableInput) setIsDraggingImage(true);
                            }}
                            onDragOver={(e) => {
                                e.preventDefault();
                                if (!disableInput) setIsDraggingImage(true);
                            }}
                            onDragLeave={(e) => {
                                e.preventDefault();
                                if (e.currentTarget.contains(e.relatedTarget as Node)) return;
                                setIsDraggingImage(false);
                            }}
                            onDrop={handleImageDrop}
                            onClick={() => !disableInput && imageInputRef.current?.click()}
                            onKeyDown={(e) => {
                                if (disableInput) return;
                                if (e.key === 'Enter' || e.key === ' ') {
                                    e.preventDefault();
                                    imageInputRef.current?.click();
                                }
                            }}
                            role="button"
                            tabIndex={disableInput ? -1 : 0}
                            aria-disabled={disableInput}
                            className={cn(
                                'border-muted-foreground/30 bg-muted/20 flex min-h-36 items-center gap-4 rounded-lg border-2 border-dashed p-4 transition-colors',
                                disableInput ? 'cursor-not-allowed opacity-70' : 'cursor-pointer',
                                isDraggingImage && 'border-primary bg-primary/5',
                            )}
                        >
                            <div className="bg-background flex h-24 w-24 shrink-0 items-center justify-center overflow-hidden rounded-md border p-2">
                                <img
                                    src={imagePreview ?? currentImageSrc}
                                    alt="Imagem do produto"
                                    className="max-h-full max-w-full object-contain"
                                    onError={(event) => {
                                        event.currentTarget.src = '/images/default.png';
                                    }}
                                />
                            </div>
                            <div className="min-w-0">
                                <UploadCloud className="text-muted-foreground mb-2 h-6 w-6" />
                                <p className="text-sm font-medium">Arraste a imagem aqui ou clique para selecionar</p>
                                <p className="text-muted-foreground mt-1 text-xs">PNG, JPG, WEBP, GIF ou SVG até 2 MB.</p>
                                {data.image && <p className="text-muted-foreground mt-2 truncate text-xs">{data.image.name}</p>}
                            </div>
                            <Input
                                ref={imageInputRef}
                                type="file"
                                id="image"
                                accept="image/*"
                                onChange={(e) => handleImageFile(e.target.files?.[0])}
                                className="sr-only"
                                disabled={disableInput}
                            />
                        </div>
                        <InputError message={errors.image} />
                    </div>

                    <div className="mt-4 grid gap-4 md:grid-cols-2">
                        <div className="grid gap-2">
                            <Label htmlFor="model_compatibility">Modelos compatíveis</Label>
                            <Input
                                type="text"
                                id="model_compatibility"
                                value={data.model_compatibility}
                                onChange={(e) => setData('model_compatibility', e.target.value)}
                                readOnly={disableInput}
                            />
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="location">Local de Armazenamento</Label>
                            <Input
                                type="text"
                                id="location"
                                value={data.location}
                                onChange={(e) => setData('location', e.target.value)}
                                readOnly={disableInput}
                            />
                        </div>
                    </div>
                </CardContent>
            </Card>

            <Card>
                <CardTitle className="border-b px-6 pb-4">Valores e estoque</CardTitle>
                <CardContent className="space-y-4 pt-6">
                    <div className="mt-4 grid gap-4 md:grid-cols-4">
                        <div className="grid gap-2">
                            <Label htmlFor="cost_price">Preço de Custo</Label>
                            <MoneyInput
                                id="cost_price"
                                value={data.cost_price}
                                onValueChange={(value) => setData('cost_price', value)}
                                readOnly={disableInput}
                                placeholder="0,00"
                                error={errors.cost_price}
                            />
                            {errors.cost_price && <div className="text-sm text-red-500">{errors.cost_price}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="sale_price">Preço de Venda</Label>
                            <MoneyInput
                                id="sale_price"
                                value={data.sale_price}
                                onValueChange={(value) => setData('sale_price', value)}
                                readOnly={disableInput}
                                placeholder="0,00"
                                error={errors.sale_price}
                            />
                            {errors.sale_price && <div className="text-sm text-red-500">{errors.sale_price}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="quantity">
                                {insertStock ? 'Inserir ao Estoque' : isEdit ? 'Alterar Estoque' : 'Quantidade do Estoque'}
                            </Label>
                            <Input
                                type="text"
                                id="quantity"
                                value={data.quantity}
                                onChange={(e) => setData('quantity', e.target.value)}
                                placeholder="0"
                            />
                            {errors.quantity && <div className="text-sm text-red-500">{errors.quantity}</div>}
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="minimum_stock_level">Estoque Mínimo</Label>
                            <Input
                                type="text"
                                id="minimum_stock_level"
                                value={data.minimum_stock_level}
                                onChange={(e) => setData('minimum_stock_level', e.target.value)}
                                readOnly={disableInput}
                                placeholder="0"
                            />
                            {errors.minimum_stock_level && <div className="text-sm text-red-500">{errors.minimum_stock_level}</div>}
                        </div>
                    </div>

                    <div className="grid gap-2">
                        <Label htmlFor="status">Status da Peça</Label>

                        <div className="flex items-center gap-3">
                            <Switch id="status" checked={data.status} onCheckedChange={(checked) => setData('status', checked)} />

                            <span className="text-muted-foreground text-sm">{data.status ? 'Ativa' : 'Inativa'}</span>
                        </div>
                    </div>
                </CardContent>
            </Card>

            <div className="flex justify-end">
                <Button type="submit" disabled={processing}>
                    <Save />
                    Salvar
                </Button>
            </div>
        </form>
    );
}

import AsyncResourceSelect from '@/components/async-resource-select';
import { Icon } from '@/components/icon';
import InputError from '@/components/input-error';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { MoneyInput } from '@/components/ui/money-input';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Textarea } from '@/components/ui/textarea';
import AppLayout from '@/layouts/app-layout';
import { formatBRL, multiplyMoney, sumMoney } from '@/lib/money';
import { BreadcrumbItem, OptionType } from '@/types';
import { Head, useForm } from '@inertiajs/react';
import { Plus, Trash2, Truck } from 'lucide-react';
import { useMemo, useState } from 'react';

type Supplier = { id: number; name: string };

type PurchaseOrderItem = {
    id?: number;
    part_id: number;
    quantity: number;
    unit_cost: number;
    part?: { id: number; name: string; reference_number?: string };
};

type PurchaseOrder = {
    id: number;
    purchase_order_number?: number;
    supplier_id?: number | null;
    expected_date?: string | null;
    notes?: string | null;
    items: PurchaseOrderItem[];
};

type ItemFormRow = {
    part_id: number | null;
    quantity: string;
    unit_cost: string;
};

type SuggestedItem = {
    part_id: number;
    part_label: string;
    quantity: number;
    unit_cost: number;
    supplier_id: number | null;
};

export default function PurchaseOrderCreate({
    purchaseOrder,
    suppliers,
    suggestedItem,
}: {
    purchaseOrder?: PurchaseOrder;
    suppliers: Supplier[];
    suggestedItem?: SuggestedItem | null;
}) {
    const isEdit = !!purchaseOrder;

    const breadcrumbs: BreadcrumbItem[] = [
        { title: 'Painel', href: route('app.dashboard') },
        { title: 'Ordens de compra', href: route('app.purchase-orders.index') },
        { title: isEdit ? 'Editar' : 'Nova ordem de compra', href: '#' },
    ];

    const emptyRow: ItemFormRow = { part_id: null, quantity: '1', unit_cost: '' };

    const initialItems: ItemFormRow[] = purchaseOrder?.items?.length
        ? purchaseOrder.items.map((item) => ({
              part_id: item.part_id,
              quantity: String(item.quantity),
              unit_cost: String(item.unit_cost),
          }))
        : suggestedItem
          ? [{ part_id: suggestedItem.part_id, quantity: String(suggestedItem.quantity), unit_cost: String(suggestedItem.unit_cost) }]
          : [emptyRow];

    const initialItemOptions: (OptionType | null)[] = purchaseOrder?.items?.length
        ? purchaseOrder.items.map((item) => ({
              value: item.part_id,
              label: item.part ? `${item.part.name}${item.part.reference_number ? ` (${item.part.reference_number})` : ''}` : `Peça #${item.part_id}`,
          }))
        : suggestedItem
          ? [{ value: suggestedItem.part_id, label: suggestedItem.part_label }]
          : [null];

    const form = useForm({
        supplier_id: purchaseOrder?.supplier_id
            ? String(purchaseOrder.supplier_id)
            : suggestedItem?.supplier_id
              ? String(suggestedItem.supplier_id)
              : '',
        expected_date: purchaseOrder?.expected_date ?? '',
        notes: purchaseOrder?.notes ?? '',
        items: initialItems,
    });

    const [itemOptions, setItemOptions] = useState<(OptionType | null)[]>(initialItemOptions);

    const addItem = () => {
        form.setData('items', [...form.data.items, emptyRow]);
        setItemOptions((options) => [...options, null]);
    };

    const removeItem = (index: number) => {
        form.setData(
            'items',
            form.data.items.filter((_, i) => i !== index),
        );
        setItemOptions((options) => options.filter((_, i) => i !== index));
    };

    const updateItem = (index: number, field: keyof ItemFormRow, value: string | number | null) => {
        const items = [...form.data.items];
        items[index] = { ...items[index], [field]: value };
        form.setData('items', items);
    };

    const total = useMemo(() => sumMoney(form.data.items.map((item) => multiplyMoney(item.unit_cost, item.quantity))), [form.data.items]);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();

        if (isEdit) {
            form.put(route('app.purchase-orders.update', purchaseOrder!.id));
            return;
        }

        form.post(route('app.purchase-orders.store'));
    };

    return (
        <AppLayout breadcrumbs={breadcrumbs}>
            <Head title={isEdit ? 'Editar ordem de compra' : 'Nova ordem de compra'} />

            <div className="flex min-h-16 flex-col justify-center gap-1 px-4 py-3">
                <div className="flex items-center gap-2">
                    <Icon iconNode={Truck} className="h-8 w-8" />
                    <h2 className="text-xl font-semibold tracking-tight">
                        {isEdit ? `Editar ordem de compra ${purchaseOrder?.purchase_order_number ?? ''}` : 'Nova ordem de compra'}
                    </h2>
                </div>
            </div>

            {!isEdit && suggestedItem && (
                <div className="mx-4 mb-2 rounded-md border border-amber-200 bg-amber-50 px-4 py-3 text-sm text-amber-800 dark:border-amber-900 dark:bg-amber-950/40 dark:text-amber-300">
                    Sugestão gerada a partir do estoque baixo de <strong>{suggestedItem.part_label}</strong>: quantidade e fornecedor foram
                    preenchidos automaticamente, revise antes de salvar.
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4 p-4">
                <Card>
                    <CardTitle className="border-b px-6 pb-4">Dados da compra</CardTitle>
                    <CardContent className="space-y-4 pt-6">
                        <div className="grid gap-4 md:grid-cols-2">
                            <div className="grid gap-2">
                                <Label htmlFor="supplier_id">Fornecedor</Label>
                                <select
                                    id="supplier_id"
                                    value={form.data.supplier_id}
                                    onChange={(e) => form.setData('supplier_id', e.target.value)}
                                    className="border-input bg-background h-10 rounded-md border px-3 text-sm"
                                >
                                    <option value="">Selecione um fornecedor</option>
                                    {suppliers.map((supplier) => (
                                        <option key={supplier.id} value={supplier.id}>
                                            {supplier.name}
                                        </option>
                                    ))}
                                </select>
                                <InputError message={form.errors.supplier_id} />
                            </div>
                            <div className="grid gap-2">
                                <Label htmlFor="expected_date">Previsão de entrega</Label>
                                <Input
                                    id="expected_date"
                                    type="date"
                                    value={form.data.expected_date}
                                    onChange={(e) => form.setData('expected_date', e.target.value)}
                                />
                                <InputError message={form.errors.expected_date} />
                            </div>
                        </div>

                        <div className="grid gap-2">
                            <Label htmlFor="notes">Observações</Label>
                            <Textarea id="notes" value={form.data.notes} onChange={(e) => form.setData('notes', e.target.value)} rows={3} />
                            <InputError message={form.errors.notes} />
                        </div>
                    </CardContent>
                </Card>

                <Card>
                    <CardTitle className="flex items-center justify-between border-b px-6 pb-4">
                        <span>Itens</span>
                        <Button type="button" size="sm" variant="outline" onClick={addItem}>
                            <Plus className="h-4 w-4" />
                            Adicionar peça
                        </Button>
                    </CardTitle>
                    <CardContent className="pt-6">
                        <InputError message={form.errors.items as string} />
                        <div className="rounded-lg border">
                            <Table>
                                <TableHeader>
                                    <TableRow>
                                        <TableHead className="min-w-[260px]">Peça</TableHead>
                                        <TableHead className="w-32">Quantidade</TableHead>
                                        <TableHead className="w-40">Custo unitário</TableHead>
                                        <TableHead className="w-32">Subtotal</TableHead>
                                        <TableHead className="w-12"></TableHead>
                                    </TableRow>
                                </TableHeader>
                                <TableBody>
                                    {form.data.items.map((item, index) => (
                                        <TableRow key={index}>
                                            <TableCell>
                                                <AsyncResourceSelect
                                                    inputId={`items.${index}.part_id`}
                                                    searchUrl={route('app.parts.search')}
                                                    value={itemOptions[index] ?? null}
                                                    onChange={(option) => {
                                                        setItemOptions((options) => {
                                                            const next = [...options];
                                                            next[index] = option;
                                                            return next;
                                                        });
                                                        updateItem(index, 'part_id', option ? Number(option.value) : null);
                                                    }}
                                                    placeholder="Buscar peça..."
                                                    mapOption={(part: any) => ({
                                                        value: part.id,
                                                        label: `${part.name}${part.reference_number ? ` (${part.reference_number})` : ''}`,
                                                    })}
                                                />
                                                <InputError message={(form.errors as any)[`items.${index}.part_id`]} />
                                            </TableCell>
                                            <TableCell>
                                                <Input
                                                    type="number"
                                                    min={1}
                                                    step={1}
                                                    value={item.quantity}
                                                    onChange={(e) => updateItem(index, 'quantity', e.target.value)}
                                                />
                                                <InputError message={(form.errors as any)[`items.${index}.quantity`]} />
                                            </TableCell>
                                            <TableCell>
                                                <MoneyInput
                                                    placeholder="0,00"
                                                    aria-label="Custo unitário"
                                                    value={item.unit_cost}
                                                    onValueChange={(value) => updateItem(index, 'unit_cost', value)}
                                                />
                                                <InputError message={(form.errors as any)[`items.${index}.unit_cost`]} />
                                            </TableCell>
                                            <TableCell>{formatBRL(multiplyMoney(item.unit_cost, item.quantity))}</TableCell>
                                            <TableCell>
                                                {form.data.items.length > 1 && (
                                                    <Button type="button" variant="ghost" size="icon" onClick={() => removeItem(index)}>
                                                        <Trash2 className="h-4 w-4" />
                                                    </Button>
                                                )}
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </div>

                        <div className="mt-4 flex justify-end text-lg font-semibold">Total: {formatBRL(total)}</div>
                    </CardContent>
                </Card>

                <div className="flex justify-end gap-2">
                    <Button type="button" variant="outline" onClick={() => window.history.back()}>
                        Cancelar
                    </Button>
                    <Button type="submit" disabled={form.processing}>
                        {isEdit ? 'Salvar alterações' : 'Salvar ordem de compra'}
                    </Button>
                </div>
            </form>
        </AppLayout>
    );
}

