export default function Receipt({
    order,
    company,
    type,
    receipt,
    checklist,
    backUrl,
    copies = 2,
}: {
    order: any;
    company: any;
    type: any;
    receipt: any;
    checklist: any;
    backUrl?: string;
    copies?: number;
}) {
    const [openAsPdf] = useState(() => {
        if (typeof window === 'undefined') return false;

        const query = new URLSearchParams(window.location.search);
        return query.get('pdf') === '1';
    });
    const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

    useEffect(() => {
        if (!openAsPdf) return;

        let isMounted = true;
        const generatePdf = async () => {
            setIsGeneratingPdf(true);
            try {
                // O gerador de PDF (~1,5 MB) só é baixado quando o usuário pede o documento.
                const [{ pdf }, { default: OrderReceiptPDF }] = await Promise.all([import('@react-pdf/renderer'), import('./pdf/OrderReceiptPDF')]);
                const blob = await pdf(
                    <OrderReceiptPDF order={order} company={company} type={type} receipt={receipt} checklist={checklist} />,
                ).toBlob();
                if (!isMounted) return;

                const url = URL.createObjectURL(blob);
                window.location.href = url;
                setTimeout(() => URL.revokeObjectURL(url), 60_000);
            } catch (error) {
                console.error('Erro ao gerar recibo em PDF:', error);
                toastError('Erro ao gerar recibo em PDF.');
            } finally {
                if (isMounted) setIsGeneratingPdf(false);
            }
        };

        generatePdf();
        return () => {
            isMounted = false;
        };
    }, [openAsPdf, order, company, type, receipt, checklist]);

    if (openAsPdf) {
        return (
            <div className="mx-auto flex min-h-[60vh] max-w-4xl items-center justify-center p-6">
                <Toaster />
                <p className="text-muted-foreground text-sm">{isGeneratingPdf ? 'Gerando recibo PDF...' : 'Abrindo recibo PDF...'}</p>
            </div>
        );
    }

    const handlePrint = () => {
        window.print();
    };
    return (
        <div className="relative mx-auto max-w-4xl">
            {/* Botão de Impressão - oculto na impressão */}
            <div className="absolute mb-4 flex w-full items-center justify-between print:hidden">
                <Button asChild className="gap-2">
                    <Link href={backUrl ?? route('app.orders.index')}>
                        <ArrowLeft className="h-4 w-4" />
                    </Link>
                </Button>
                <Button onClick={handlePrint} className="gap-2">
                    <Printer className="h-4 w-4" />
                </Button>
            </div>

            {/* Recibo para Impressão */}
            <div className="bg-white shadow-lg print:h-screen print:shadow-none">
                {/* Primeira Via */}
                <ReceiptCopy order={order} company={company} type={type} receipt={receipt} checklist={checklist} qrcode={false} />

                {/* Segunda Via */}
                {copies > 1 && <ReceiptCopy order={order} company={company} type={type} receipt={receipt} checklist={checklist} qrcode={false} />}
            </div>
        </div>
    );
}

import { toastError } from '@/components/app-toast-messages';
import { Button } from '@/components/ui/button';
import { router } from '@inertiajs/react';
import { FileText, Loader2 } from 'lucide-react';
import moment from 'moment';
import { useState } from 'react';

interface DateRange {
    from?: Date;
    to?: Date;
}

export default function CashierReport({ dateRange, company }: { dateRange?: DateRange; company: string }) {
    const [loading, setLoading] = useState(false);

    async function handleGeneratePDF() {
        if (!dateRange?.from || !dateRange?.to) return;
        setLoading(true);
        const previewWindow = window.open('', '_blank');

        if (!previewWindow) {
            setLoading(false);
            return;
        }

        previewWindow.document.title = 'Gerando relatório...';
        previewWindow.document.body.innerHTML = '<p style="font-family: Arial, sans-serif; padding: 16px;">Gerando relatório PDF...</p>';

        router.post(
            route('app.reports.store'),
            {
                type: 'cashier',
                from: moment(dateRange.from).format('YYYY-MM-DD'),
                to: moment(dateRange.to).format('YYYY-MM-DD'),
            },
            {
                preserveState: true,
                preserveScroll: true,
                onSuccess: async (page: any) => {
                    const reportData = page.props?.reportData || [];
                    const reportMeta = page.props?.reportMeta || {};

                    // O gerador de PDF (~1,5 MB) só é baixado quando o usuário pede o documento.
                    const [{ pdf }, { default: CashierPeriodReportPDF }] = await Promise.all([
                        import('@react-pdf/renderer'),
                        import('./pdf/CashierPeriodReportPDF'),
                    ]);
                    const blob = await pdf(
                        <CashierPeriodReportPDF data={reportData} dateRange={dateRange} company={company} reportMeta={reportMeta} />,
                    ).toBlob();

                    const url = URL.createObjectURL(blob);
                    previewWindow.location.href = url;
                },
                onError: (errors) => {
                    toastError('Não foi possível gerar o relatório', Object.values(errors)[0] as string);
                    previewWindow.close();
                },
                onFinish: () => setLoading(false),
            },
        );
    }

    return (
        <div className="flex w-full justify-center">
            <Button onClick={handleGeneratePDF} disabled={loading || !dateRange?.from || !dateRange?.to} className="w-full">
                {loading ? (
                    <>
                        <Loader2 className="mr-2 size-4 animate-spin" />
                        Gerando PDF...
                    </>
                ) : (
                    <>
                        <FileText className="mr-2 size-4" />
                        Caixa por Período
                    </>
                )}
            </Button>
        </div>
    );
}

