                                        className="flex items-center justify-between gap-3 rounded-md border px-3 py-2 text-sm"
                                    >
                                        <div className="flex min-w-0 items-center gap-2">
                                            <CheckCircle2 className="h-4 w-4 shrink-0 text-emerald-600" />
